CREATE OR REPLACE FUNCTION public.admin_reject_referral(p_referral_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_credit public.wallet_ledger%rowtype;
  v_cancelled boolean := false;
begin
  if not public.am_i_admin() then
    raise exception 'admin only' using errcode = '42501';
  end if;
  update public.referrals
     set status = 'rejected', reject_reason = left(coalesce(nullif(trim(p_reason), ''), 'rejected by admin'), 500)
   where id = p_referral_id and status <> 'rejected';
  if not found then
    raise exception 'Referral not found or already rejected';
  end if;
  select * into v_credit from public.wallet_ledger
   where referral_id = p_referral_id and entry_type = 'credit' and source = 'referral_reward' for update;
  if found and v_credit.status = 'pending' then
    perform set_config('app.trusted_order_write', 'true', true);
    update public.wallet_ledger set status = 'cancelled' where id = v_credit.id;
    perform set_config('app.trusted_order_write', 'false', true);
    v_cancelled := true;
  end if;
  return jsonb_build_object('credit_cancelled', v_cancelled,
                            'credit_already_released', found and v_credit.status = 'available');
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_resolve_order_flag(p_flag_id uuid, p_note text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.am_i_admin() then
    raise exception 'admin only' using errcode = '42501';
  end if;
  perform set_config('app.trusted_order_write', 'true', true);
  update public.order_review_flags
     set resolved_at = now(), resolved_by = auth.uid(), resolution_note = left(coalesce(p_note, ''), 500)
   where id = p_flag_id and resolved_at is null;
  perform set_config('app.trusted_order_write', 'false', true);
  if not found then raise exception 'Flag not found or already resolved'; end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_reverse_wallet_credit(p_ledger_id uuid, p_note text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row public.wallet_ledger%rowtype;
  v_avail numeric(10, 2);
  v_amt numeric(10, 2);
begin
  if not public.am_i_admin() then
    raise exception 'admin only' using errcode = '42501';
  end if;
  select * into v_row from public.wallet_ledger where id = p_ledger_id for update;
  if not found or v_row.entry_type <> 'credit' or v_row.status <> 'available' then
    raise exception 'Only an available credit can be reversed';
  end if;
  if v_row.user_id is null then
    raise exception 'This credit belongs to a deleted account';
  end if;
  if v_row.expires_at is not null and v_row.expires_at <= now() then
    raise exception 'This credit has already expired';
  end if;
  if exists (select 1 from public.wallet_ledger where entry_type = 'reversal' and reverses_id = v_row.id) then
    raise exception 'This credit was already reversed';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('wallet:' || v_row.user_id::text, 0));
  select available into v_avail from public.wallet_balance_of(v_row.user_id);
  v_amt := least(v_row.amount, coalesce(v_avail, 0));
  if v_amt <= 0 then
    raise exception 'Nothing left to reverse: the student has already spent this credit';
  end if;

  perform set_config('app.trusted_order_write', 'true', true);
  insert into public.wallet_ledger (user_id, entry_type, status, amount, source, reverses_id, referral_id, note)
  values (v_row.user_id, 'reversal', 'available', v_amt, 'admin_adjustment', v_row.id, v_row.referral_id,
          left(coalesce(p_note, 'admin reversal')
               || case when v_amt < v_row.amount then ' (partial: ' || v_amt || ' of ' || v_row.amount || ' was still available)' else '' end, 500));
  perform set_config('app.trusted_order_write', 'false', true);
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_set_order_status(p_order_id text, p_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.am_i_admin() then
    raise exception 'admin only' using errcode = '42501';
  end if;
  if p_status not in ('cancelled', 'failed') then
    raise exception 'Admins can only cancel or fail an order; paid is set by the payment system';
  end if;
  update public.orders
  set status = p_status, updated_at = now()
  where id = p_order_id
    and status = 'created'
    and razorpay_payment_id is null
    and not exists (select 1 from public.payments p where p.order_id = orders.id);
  if not found then
    raise exception 'Order not found, or it is already paid / settled';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.analytics_events_rate_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if coalesce(current_setting('role', true), 'none') in ('anon', 'authenticated') then
    if new.user_id is null then
      if not public.rate_limit_hit('analytics-anon', 300, 60) then return null; end if;
    elsif not public.rate_limit_hit('analytics-user:' || new.user_id::text, 600, 3600) then
      return null;
    end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.app_config_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  new.updated_at := now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_referral_code(p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_settings public.referral_settings%rowtype;
  v_referrer public.profiles%rowtype;
  v_caller public.profiles%rowtype;
  v_referral_count integer;
  v_code text;
begin
  if v_uid is null then
    return jsonb_build_object('status', 'error', 'message', 'Not authenticated.');
  end if;
  if p_code is null or length(trim(p_code)) = 0 then
    return jsonb_build_object('status', 'invalid_code', 'message', 'Please enter a referral code.');
  end if;
  v_code := upper(trim(p_code));

  -- 10 attempts per user per hour: enough for typos, useless for guessing codes.
  if not public.rate_limit_hit('apply-referral:' || v_uid::text, 10, 3600) then
    return jsonb_build_object('status', 'rate_limited', 'message', 'Too many attempts. Please try again later.');
  end if;

  select * into v_settings from public.referral_settings where id = true;
  if v_settings is null or not v_settings.enabled then
    return jsonb_build_object('status', 'disabled', 'message', 'Referrals are not available right now.');
  end if;

  select * into v_caller from public.profiles where id = v_uid;
  if v_caller is null then
    return jsonb_build_object('status', 'error', 'message', 'Profile not found.');
  end if;
  if v_settings.require_verified_phone and not v_caller.mobile_verified then
    return jsonb_build_object('status', 'phone_not_verified', 'message', 'Verify your mobile number to use a referral code.');
  end if;

  select * into v_referrer from public.profiles where referral_code = v_code;
  if v_referrer is null then
    return jsonb_build_object('status', 'invalid_code', 'message', 'That referral code was not found.');
  end if;
  if v_referrer.id = v_uid then
    return jsonb_build_object('status', 'self_referral', 'message', 'You cannot refer yourself.');
  end if;
  if v_referrer.blocked then
    return jsonb_build_object('status', 'referrer_blocked', 'message', 'That referral code is no longer active.');
  end if;
  -- An unverified referrer's code behaves exactly like an unknown one.
  if v_settings.require_verified_phone and not v_referrer.mobile_verified then
    return jsonb_build_object('status', 'invalid_code', 'message', 'That referral code was not found.');
  end if;
  if exists (select 1 from public.referrals where referred_id = v_uid) then
    return jsonb_build_object('status', 'already_referred', 'message', 'A referral code has already been applied to your account.');
  end if;
  if v_caller.created_at < now() - make_interval(days => v_settings.apply_window_days) then
    return jsonb_build_object('status', 'too_late', 'message', 'Referral codes can only be used when you sign up.');
  end if;
  if exists (select 1 from public.purchases where user_id = v_uid and status = 'success')
     or exists (select 1 from public.orders where user_id = v_uid and status = 'paid') then
    return jsonb_build_object('status', 'already_purchased', 'message', 'Referral codes must be applied before your first purchase.');
  end if;

  -- same email / phone already bought under another (maybe deleted) account: not a first purchase
  if public.has_prior_purchase_identity(v_uid) then
    return jsonb_build_object('status', 'already_purchased', 'message', 'Referral codes must be applied before your first purchase.');
  end if;

  if v_settings.max_referrals_per_user is not null then
    -- One applier at a time per referrer, so the count below cannot go stale.
    perform pg_advisory_xact_lock(hashtextextended('referrer:' || v_referrer.id::text, 0));
    select count(*) into v_referral_count from public.referrals
     where referrer_id = v_referrer.id and status <> 'rejected';
    if v_referral_count >= v_settings.max_referrals_per_user then
      return jsonb_build_object('status', 'referrer_limit_reached', 'message', 'That referral code has reached its usage limit.');
    end if;
  end if;

  insert into public.referrals (referrer_id, referred_id, code_used, status)
  values (v_referrer.id, v_uid, v_code, 'pending');

  return jsonb_build_object('status', 'success', 'message', 'Referral applied successfully.');
exception
  when unique_violation then
    return jsonb_build_object('status', 'already_referred', 'message', 'A referral code has already been applied to your account.');
end;
$function$

CREATE OR REPLACE FUNCTION public.attach_ucb_external_token(p_user_id uuid, p_order_id text, p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare o public.orders%rowtype;
begin
  if p_token is null or length(p_token)<10 or length(p_token)>4096 or p_token ~ '[[:space:][:cntrl:]]' then
    return jsonb_build_object('ok',false,'code','invalid_token'); end if;
  perform pg_advisory_xact_lock(hashtextextended('wallet:' || p_user_id::text,0));
  select * into o from public.orders where id=p_order_id for update;
  if not found or o.user_id is distinct from p_user_id or o.provider<>'play' or o.purchase_token is not null or o.play_sku is null then
    return jsonb_build_object('ok',false,'code','order_unavailable'); end if;
  if o.external_choice_bound_order_id is not null then
    if exists(select 1 from public.orders where id=o.external_choice_bound_order_id
      and user_id=p_user_id and product_id=o.product_id and provider='razorpay' and external_transaction_token=p_token) then
      return jsonb_build_object('ok',true); end if;
    return jsonb_build_object('ok',false,'code','token_already_attached');
  end if;
  if o.status<>'created' or o.expires_at is null or o.expires_at<=now() then
    return jsonb_build_object('ok',false,'code','order_unavailable'); end if;
  if o.external_transaction_token is not null and o.external_transaction_token<>p_token then
    return jsonb_build_object('ok',false,'code','token_already_attached'); end if;
  if exists(select 1 from public.orders where external_transaction_token=p_token and id<>p_order_id) then
    return jsonb_build_object('ok',false,'code','token_already_attached'); end if;
  update public.orders set external_transaction_token=p_token where id=p_order_id and external_transaction_token is null;
  return jsonb_build_object('ok',true);
exception when unique_violation then
  return jsonb_build_object('ok',false,'code','token_already_attached');
end $function$

CREATE OR REPLACE FUNCTION public.bind_ucb_razorpay_order(p_user_id uuid, p_choice_id text, p_razorpay_id text, p_buyer_state text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_choice public.orders%rowtype; v_paid public.orders%rowtype;
begin
  if p_buyer_state is null or not (p_buyer_state = any(array[
    'ANDAMAN AND NICOBAR ISLANDS','ANDHRA PRADESH','ARUNACHAL PRADESH','ASSAM','BIHAR','CHANDIGARH',
    'CHHATTISGARH','DADRA AND NAGAR HAVELI','DADRA AND NAGAR HAVELI AND DAMAN AND DIU',
    'DAMAN AND DIU','DELHI','GOA','GUJARAT','HARYANA','HIMACHAL PRADESH','JAMMU AND KASHMIR',
    'JHARKHAND','KARNATAKA','KERALA','LADAKH','LAKSHADWEEP','MADHYA PRADESH','MAHARASHTRA',
    'MANIPUR','MEGHALAYA','MIZORAM','NAGALAND','ODISHA','PUDUCHERRY','PUNJAB','RAJASTHAN',
    'SIKKIM','TAMIL NADU','TELANGANA','TRIPURA','UTTAR PRADESH','UTTARAKHAND','WEST BENGAL'])) then
    return jsonb_build_object('ok',false,'code','buyer_state_invalid');
  end if;
  perform pg_advisory_xact_lock(hashtextextended('wallet:' || p_user_id::text, 0));
  select * into v_choice from public.orders where id=p_choice_id for update;
  select * into v_paid from public.orders where razorpay_order_id=p_razorpay_id for update;
  if v_choice.id is null or v_paid.id is null or v_choice.user_id is distinct from p_user_id
     or v_paid.user_id is distinct from p_user_id or v_choice.product_id is distinct from v_paid.product_id
     or v_choice.provider<>'play' or v_paid.provider<>'razorpay' or v_choice.status<>'cancelled'
     or v_paid.status<>'created' or v_choice.external_transaction_token is null
     or v_choice.purchase_token is not null or v_choice.play_sku is null
     or v_paid.external_transaction_token is not null then
    return jsonb_build_object('ok',false,'code','ucb_binding_failed');
  end if;
  if v_paid.tax_pre_amount is null or v_paid.tax_amount is null or v_paid.gst_rate_percent is null
     or v_paid.tax_pre_amount+v_paid.tax_amount<>v_paid.amount then
    return jsonb_build_object('ok',false,'code','tax_snapshot_missing');
  end if;
  update public.orders set external_transaction_token=null,external_choice_bound_order_id=v_paid.id where id=v_choice.id;
  update public.orders set external_transaction_token=v_choice.external_transaction_token,
    external_transaction_id='medveda_' || replace(v_paid.id,'-',''),
    external_report_status='pending',play_sku=v_choice.play_sku,
    tax_region_code='IN',tax_administrative_area=p_buyer_state where id=v_paid.id;
  return jsonb_build_object('ok',true,'order_id',v_paid.id);
end; $function$

CREATE OR REPLACE FUNCTION public.change_my_phone(p_phone text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_norm text;
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;
  if exists (select 1 from public.profiles where id = v_uid and coalesce(blocked, false)) then
    return jsonb_build_object('ok', false, 'code', 'unavailable');
  end if;

  -- Every call counts, successful or not: this is what bounds number probing.
  if not public.rate_limit_hit('phone-change:' || v_uid::text, 5, 86400) then
    return jsonb_build_object('ok', false, 'code', 'rate_limited');
  end if;

  if p_phone is null or btrim(p_phone) = '' then
    v_norm := null;                       -- clearing the number is allowed
  else
    v_norm := public.normalize_phone(p_phone);
    if v_norm is null then
      return jsonb_build_object('ok', false, 'code', 'invalid');
    end if;
  end if;

  perform set_config('app.allow_profile_admin_fields', 'true', true);
  begin
    update public.profiles
       set phone = v_norm,
           mobile_verified = false,
           updated_at = now()
     where id = v_uid
       and phone_normalized is distinct from v_norm;
  exception when unique_violation then
    perform set_config('app.allow_profile_admin_fields', 'false', true);
    -- Same answer as any other refusal: does not reveal that the number is registered.
    return jsonb_build_object('ok', false, 'code', 'unavailable');
  end;
  perform set_config('app.allow_profile_admin_fields', 'false', true);

  return jsonb_build_object('ok', true);
end;
$function$

CREATE OR REPLACE FUNCTION public.chapters_derive_course()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_course_id text;
  v_year_id text;
begin
  select course_id, year_id into v_course_id, v_year_id from public.subjects where id = new.subject_id;
  if v_course_id is null then
    raise exception 'Unknown subject_id % on chapters', new.subject_id;
  end if;
  if new.course_id is null then
    new.course_id := v_course_id;
  elsif new.course_id is distinct from v_course_id then
    raise exception 'chapters.course_id (%) does not match its subject''s course (%)', new.course_id, v_course_id;
  end if;
  if new.year_id is null then
    new.year_id := v_year_id;
  elsif new.year_id is distinct from v_year_id then
    raise exception 'chapters.year_id (%) does not match its subject''s year (%)', new.year_id, v_year_id;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.chapters_propagate_course_move()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.year_id is distinct from old.year_id or new.course_id is distinct from old.course_id then
    update public.notes set year_id = new.year_id, course_id = new.course_id
      where chapter_id = new.id and (year_id is distinct from new.year_id or course_id is distinct from new.course_id);
    update public.products set course_id = new.course_id
      where scope = 'chapter' and chapter_id = new.id and course_id is distinct from new.course_id;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_note_pdf_validation()
 RETURNS TABLE(request_id uuid, lease_id uuid, expected_bytes bigint, sha256 text, object_path text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_id uuid; v_lease uuid := gen_random_uuid();
begin
  select j.request_id into v_id from public.note_pdf_validation_jobs j
    where (j.status='pending' or (j.status='working' and j.lease_until<now()))
    and j.updated_at <= now() and j.attempts<5
    order by j.updated_at for update skip locked limit 1;
  if v_id is null then return; end if;
  update public.note_pdf_validation_jobs j set status='working',lease_id=v_lease,
    lease_until=now()+interval '10 minutes',attempts=attempts+1,updated_at=now() where j.request_id=v_id;
  return query select u.request_id,v_lease,j.expected_bytes,u.sha256,u.object_path
    from public.note_upload_requests u join public.note_pdf_validation_jobs j using(request_id)
    where u.request_id=v_id;
end $function$

CREATE OR REPLACE FUNCTION public.claim_play_price_sync()
 RETURNS TABLE(price_inr numeric, candidate_sku text, purchase_option_id text, lease_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_row public.play_price_sync%rowtype; v_lease uuid := gen_random_uuid();
begin
  select * into v_row from public.play_price_sync s
    where ((s.status = 'pending' and s.next_attempt_at <= now())
       or (s.status='running' and s.lease_until < now()))
    and exists(select 1 from public.products p where p.price=s.price_inr
      and public.play_notes_product_eligible(p))
    order by s.next_attempt_at, s.price_inr for update skip locked limit 1;
  if not found then return; end if;
  update public.play_price_sync s set status='running', lease_id=v_lease,
    lease_until=now()+interval '3 minutes', attempts=s.attempts+1, updated_at=now()
    where s.price_inr=v_row.price_inr;
  insert into public.play_price_sync_logs(price_inr,play_sku,event)
    values(v_row.price_inr,v_row.candidate_sku,'claimed');
  price_inr:=v_row.price_inr; candidate_sku:=v_row.candidate_sku;
  purchase_option_id:=v_row.purchase_option_id; lease_id:=v_lease;
  return next;
end; $function$

CREATE OR REPLACE FUNCTION public.claim_play_recovery_cursor()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v public.play_recovery_cursor%rowtype;
begin
  update public.play_recovery_cursor set lease_id=gen_random_uuid(),
    lease_until=now()+interval '3 minutes',updated_at=now()
  where id=true and next_attempt_at<=now() and (lease_until is null or lease_until<now())
  returning * into v;
  if not found then return jsonb_build_object('ok',false,'code','busy'); end if;
  return jsonb_build_object('ok',true,'lease_id',v.lease_id,'start_time_ms',v.start_time_ms,
    'end_time_ms',v.end_time_ms,'next_page_token',v.next_page_token);
end $function$

CREATE OR REPLACE FUNCTION public.claim_play_void_sweep()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_state public.play_void_sweep_state%rowtype; v_lease uuid:=gen_random_uuid();
begin
  update public.play_void_sweep_state set lease_id=v_lease,
    lease_until=now()+interval '90 seconds',updated_at=now()
  where id=true and (lease_until is null or lease_until<now()) returning * into v_state;
  if not found then return jsonb_build_object('ok',false,'code','busy'); end if;
  return jsonb_build_object('ok',true,'lease_id',v_lease,'start_time_ms',v_state.start_time_ms,
    'end_time_ms',v_state.end_time_ms,'next_page_token',v_state.next_page_token);
end $function$

CREATE OR REPLACE FUNCTION public.claim_ucb_external_refund(p_refund_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_ref public.ucb_external_refunds%rowtype; v_order_id text;
begin
  select order_id into v_order_id from public.ucb_external_refunds where refund_id=p_refund_id;
  if v_order_id is null then return jsonb_build_object('ok',false); end if;
  perform pg_advisory_xact_lock(hashtextextended('ucb-refund:' || v_order_id,0));
  select * into v_ref from public.ucb_external_refunds where refund_id=p_refund_id for update;
  if not found or v_ref.status='reported' then return jsonb_build_object('ok',false); end if;
  if v_ref.status='processing' and v_ref.attempted_at>now()-interval '2 minutes' then
    return jsonb_build_object('ok',false);
  end if;
  -- A later webhook can arrive while an earlier/later refund is already being
  -- sent to Google. Never send two refunds for one order concurrently.
  if exists(select 1 from public.ucb_external_refunds busy
     where busy.order_id=v_ref.order_id and busy.refund_id<>v_ref.refund_id
       and busy.status='processing' and busy.attempted_at>now()-interval '2 minutes') then
    return jsonb_build_object('ok',false);
  end if;
  -- Later refunds wait for earlier ones, so currentPreTaxAmount is a useful
  -- reconciliation value after an ambiguous Google response.
  if exists(select 1 from public.ucb_external_refunds prior
     where prior.order_id=v_ref.order_id and prior.refund_id<>v_ref.refund_id
       and (prior.refund_time,prior.refund_id)<(v_ref.refund_time,v_ref.refund_id)
       and prior.status<>'reported') then return jsonb_build_object('ok',false); end if;
  update public.ucb_external_refunds set status='processing',attempts=attempts+1,
    attempted_at=now(),error=null where refund_id=p_refund_id;
  return jsonb_build_object('ok',true);
end; $function$

CREATE OR REPLACE FUNCTION public.create_play_order(p_user_id uuid, p_product_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_product public.products%rowtype; v_profile public.profiles%rowtype;
  v_sku text; v_option text; v_order_id text := gen_random_uuid()::text; v_minutes integer;
begin
  perform pg_advisory_xact_lock(hashtextextended('wallet:' || p_user_id::text, 0));
  select * into v_profile from public.profiles where id=p_user_id;
  if not found or v_profile.blocked then return jsonb_build_object('ok',false,'code','account_unavailable'); end if;
  select * into v_product from public.products where id=p_product_id and active;
  if not found or v_product.course_id is distinct from v_profile.course_id then return jsonb_build_object('ok',false,'code','product_unavailable'); end if;
  if not public.play_notes_product_eligible(v_product) then
    return jsonb_build_object('ok',false,'code','not_billable_notes');
  end if;
  if exists(select 1 from public.purchases where user_id=p_user_id and product_id=p_product_id and status='success') then return jsonb_build_object('ok',false,'code','already_owned'); end if;
  select t.play_sku,t.purchase_option_id into v_sku,v_option
    from public.play_price_tiers t join public.play_price_sync s on s.candidate_sku=t.play_sku
    where t.price_inr=v_product.price and t.active and t.verified_at > now()-interval '24 hours'
      and t.currency_code='INR' and t.region_code='IN' and s.status='ready';
  if v_sku is null then return jsonb_build_object('ok',false,'code','price_tier_pending'); end if;
  select checkout_expiry_minutes into v_minutes from public.referral_settings where id=true;
  update public.orders set status='cancelled',updated_at=now() where user_id=p_user_id and status='created' and provider='play' and purchase_token is null;
  insert into public.orders(id,user_id,product_id,scope,chapter_id,subject_id,year_id,year_ids,course_id,
    amount,list_price,provider,play_sku,play_purchase_option_id,status,expires_at)
  values(v_order_id,p_user_id,p_product_id,v_product.scope,v_product.chapter_id,v_product.subject_id,v_product.year_id,
    v_product.year_ids,v_product.course_id,v_product.price,v_product.price,'play',v_sku,v_option,'created',now()+make_interval(mins=>coalesce(v_minutes,30)));
  return jsonb_build_object('ok',true,'order_id',v_order_id,'play_sku',v_sku,'purchase_option_id',v_option);
end; $function$

CREATE OR REPLACE FUNCTION public.create_priced_order(p_user_id uuid, p_product_id text, p_use_wallet boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_result jsonb; v_order public.orders%rowtype;
begin
  v_result:=public.create_priced_order_legacy(p_user_id,p_product_id,p_use_wallet);
  if coalesce((v_result->>'ok')::boolean,false) then
    select * into v_order from public.orders where id=v_result->>'order_id';
    v_result:=v_result || jsonb_build_object('amount',v_order.amount,
      'referral_discount',v_order.referral_discount,'wallet_amount',v_order.wallet_amount);
  end if;
  return v_result;
end $function$

CREATE OR REPLACE FUNCTION public.create_priced_order_legacy(p_user_id uuid, p_product_id text, p_use_wallet boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_set      public.referral_settings%rowtype;
  v_product  public.products%rowtype;
  v_ref      public.referrals%rowtype;
  v_price    numeric(10, 2);
  v_discount numeric(10, 2) := 0;
  v_wallet   numeric(10, 2) := 0;
  v_base     numeric(10, 2);
  v_cap      numeric(10, 2);
  v_balance  numeric(10, 2);
  v_final    numeric(10, 2);
  v_order_id text := gen_random_uuid()::text;
begin
  perform pg_advisory_xact_lock(hashtextextended('wallet:' || p_user_id::text, 0));

  select * into v_product from public.products where id = p_product_id;
  if not found or not v_product.active or not (v_product.price > 0) then
    return jsonb_build_object('ok', false, 'code', 'product_unavailable');
  end if;
  v_price := v_product.price::numeric(10, 2);
  if v_price < 1 then
    return jsonb_build_object('ok', false, 'code', 'invalid_price');
  end if;

  -- Already owns this exact product? Refuse before anything is reserved.
  if exists (select 1 from public.purchases
              where user_id = p_user_id and product_id = v_product.id and status = 'success') then
    return jsonb_build_object('ok', false, 'code', 'already_owned');
  end if;

  select * into v_set from public.referral_settings where id = true;

  -- Friend discount: first purchase only, code applied at signup, program on.
  if v_set.enabled and v_set.friend_discount_percent > 0 then
    select r.* into v_ref
      from public.referrals r
      join public.profiles rp on rp.id = r.referrer_id and not rp.blocked
     where r.referred_id = p_user_id
       and r.status in ('pending', 'qualified')
       and r.first_order_id is null
       and not exists (select 1 from public.purchases pu
                        where pu.user_id = p_user_id and pu.status = 'success')
       -- a returning customer (same email / phone bought under an earlier, maybe deleted, account) is not a first-time buyer
       and not public.has_prior_purchase_identity(p_user_id);
    if found then
      v_discount := round(v_price * v_set.friend_discount_percent / 100, 2);
      if v_set.friend_discount_max is not null then
        v_discount := least(v_discount, v_set.friend_discount_max);
      end if;
      v_discount := greatest(0, least(v_discount, v_price - 1));
    end if;
  end if;

  v_base := v_price - v_discount;

  -- Wallet: eligible product types only (referral_settings), capped at wallet_max_percent of what is left
  -- after the friend discount, and never more than the available balance.
  -- Program off: a client-sent use_wallet is ignored (priced with no wallet), never an error.
  if p_use_wallet and v_set.enabled then
    if not (v_product.product_type = any (v_set.wallet_product_types)) then
      return jsonb_build_object('ok', false, 'code', 'wallet_not_allowed');
    end if;
    perform public.release_due_wallet_credits(p_user_id);
    select available into v_balance from public.wallet_balance_of(p_user_id);
    v_cap := floor(v_base * v_set.wallet_max_percent) / 100;
    v_wallet := greatest(0, least(v_cap, coalesce(v_balance, 0)));
  end if;

  v_final := v_price - v_discount - v_wallet;
  if v_final < 1 then
    return jsonb_build_object('ok', false, 'code', 'invalid_price');
  end if;

  -- Validation passed: only now cancel every earlier unpaid order of this user.
  update public.orders
     set status = 'cancelled', updated_at = now()
   where user_id = p_user_id and status = 'created';

  insert into public.orders (
    id, user_id, product_id, scope, chapter_id, subject_id, year_id, year_ids, course_id,
    amount, list_price, referral_discount, wallet_amount, referral_id, status, expires_at
  ) values (
    v_order_id, p_user_id, v_product.id, v_product.scope, v_product.chapter_id, v_product.subject_id,
    v_product.year_id, v_product.year_ids, v_product.course_id,
    v_final, v_price, v_discount, v_wallet,
    case when v_discount > 0 then v_ref.id end, 'created',
    now() + make_interval(mins => v_set.checkout_expiry_minutes)
  );

  if v_wallet > 0 then
    insert into public.wallet_order_reservations(order_id,user_id,amount,expires_at)
    values (v_order_id,p_user_id,v_wallet,now() + make_interval(mins => v_set.checkout_expiry_minutes));
  end if;

  return jsonb_build_object(
    'ok', true, 'order_id', v_order_id, 'title', v_product.title,
    'list_price', v_price, 'referral_discount', v_discount,
    'wallet_amount', v_wallet, 'amount', v_final,
    'timeout_seconds', v_set.checkout_expiry_minutes * 60
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.delete_my_account()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_res jsonb;
begin
  if v_uid is null then
    raise exception 'Not authenticated';
  end if;
  -- Transaction-local flag so the orders guard (Phase 1A, part B2) lets this
  -- server-side cleanup anonymise the user's orders, including the FK
  -- ON DELETE SET NULL updates fired by the auth.users delete below. Only this
  -- function sets it; clients cannot set custom GUCs through the API.
  perform set_config('app.trusted_order_write', 'true', true);
  v_res := public.erase_user_data(v_uid);
  if v_res->>'status' = 'admin_blocked' then
    perform set_config('app.trusted_order_write', 'false', true);
    raise exception 'Admin accounts cannot be deleted from the app';
  end if;
  delete from auth.users where id = v_uid;
  perform set_config('app.trusted_order_write', 'false', true);
end;
$function$

CREATE OR REPLACE FUNCTION public.erase_user_data(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_counts jsonb := '{}'::jsonb;
  n bigint;
begin
  if p_user_id is null then
    raise exception 'user id required';
  end if;

  -- Admin accounts are referenced by admins.id (no cascade); refuse.
  if exists (select 1 from public.admins where id = p_user_id) then
    return jsonb_build_object('status', 'admin_blocked');
  end if;

  delete from public.analytics_events where user_id = p_user_id;
  get diagnostics n = row_count; v_counts := v_counts || jsonb_build_object('analytics_events', n);
  delete from public.quiz_scores where user_id = p_user_id;
  get diagnostics n = row_count; v_counts := v_counts || jsonb_build_object('quiz_scores', n);
  delete from public.push_tokens where user_id = p_user_id;
  get diagnostics n = row_count; v_counts := v_counts || jsonb_build_object('push_tokens', n);
  delete from public.payment_sessions where user_id = p_user_id;
  get diagnostics n = row_count; v_counts := v_counts || jsonb_build_object('payment_sessions', n);
  delete from public.purchases where user_id = p_user_id;
  get diagnostics n = row_count; v_counts := v_counts || jsonb_build_object('purchases', n);
  delete from public.referrals where referrer_id = p_user_id or referred_id = p_user_id;
  get diagnostics n = row_count; v_counts := v_counts || jsonb_build_object('referrals', n);

  -- Retained for tax/accounting: anonymise instead of delete.
  update public.payments set user_id = null where user_id = p_user_id;
  get diagnostics n = row_count; v_counts := v_counts || jsonb_build_object('payments_anonymised', n);
  update public.orders set user_id = null where user_id = p_user_id;
  get diagnostics n = row_count; v_counts := v_counts || jsonb_build_object('orders_anonymised', n);

  delete from public.profiles where id = p_user_id;
  get diagnostics n = row_count; v_counts := v_counts || jsonb_build_object('profiles', n);

  return jsonb_build_object('status', 'erased', 'counts', v_counts);
end;
$function$

CREATE OR REPLACE FUNCTION public.fail_play_price_sync(p_price numeric, p_lease uuid, p_reason text, p_retry boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_sku text; v_attempts integer;
begin
  select candidate_sku,attempts into v_sku,v_attempts from public.play_price_sync
    where price_inr=p_price and lease_id=p_lease and status='running' and lease_until>now() for update;
  if not found then return false; end if;
  update public.play_price_sync set status=case when p_retry and v_attempts<12 then 'pending' else 'failed' end,
    next_attempt_at=now()+make_interval(secs=>least(3600,15*power(2,least(v_attempts,8)))::integer),
    lease_id=null,lease_until=null,last_error=left(p_reason,300),updated_at=now() where price_inr=p_price;
  insert into public.play_price_sync_logs(price_inr,play_sku,event,detail)
    values(p_price,v_sku,case when p_retry and v_attempts<12 then 'retry' else 'failed' end,left(p_reason,300));
  return true;
end; $function$

CREATE OR REPLACE FUNCTION public.finish_note_pdf_validation(p_request_id uuid, p_lease uuid, p_outcome text, p_error text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if p_outcome not in ('complete','rejected','pending') or p_outcome is null then
    raise exception 'Invalid validation outcome' using errcode='22023';
  end if;
  perform 1 from public.note_pdf_validation_jobs where request_id=p_request_id
    and status='working' and lease_id=p_lease and lease_until>now() for update;
  if not found then return false; end if;
  if p_outcome='complete' then
    update public.note_upload_requests set status='uploaded',updated_at=now()
      where request_id=p_request_id and status='reserved';
  end if;
  update public.note_pdf_validation_jobs set status=p_outcome,lease_until=null,lease_id=null,
    last_error=left(p_error,300),updated_at=now()+case when p_outcome='pending' then interval '1 minute' else interval '0' end
    where request_id=p_request_id;
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.finish_payment_job(p_kind text, p_target_id text, p_lease_id uuid, p_success boolean, p_error text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_attempts integer; v_status text;
begin
  select attempts into v_attempts from public.payment_jobs
    where kind=p_kind and target_id=p_target_id and lease_id=p_lease_id and status='leased' for update;
  if not found then return 'lease_lost'; end if;
  v_status:=case when p_success then 'done' when v_attempts>=12 then 'parked' else 'pending' end;
  update public.payment_jobs set status=v_status,lease_id=null,lease_until=null,
    last_error=case when p_success then null else left(coalesce(p_error,'failed'),300) end,
    next_attempt_at=case when p_success then now() else
      now()+make_interval(secs=>least(3600,60*power(2,least(v_attempts-1,6)))::integer) end
    where kind=p_kind and target_id=p_target_id;
  return v_status;
end $function$

CREATE OR REPLACE FUNCTION public.finish_play_payment_job(p_kind text, p_order_id text, p_lease_id uuid, p_success boolean, p_error text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_attempts integer; v_status text;
begin
  select attempts into v_attempts from public.play_payment_jobs
    where kind=p_kind and order_id=p_order_id and lease_id=p_lease_id
      and status='leased' and lease_until>now() for update;
  if not found then return 'lease_lost'; end if;
  v_status:=case when p_success then 'done' when v_attempts>=12 then 'parked' else 'pending' end;
  update public.play_payment_jobs set status=v_status,lease_id=null,lease_until=null,
    last_error=case when p_success then null else left(coalesce(p_error,'failed'),300) end,
    next_attempt_at=case when p_success then now() else
      now()+make_interval(secs=>least(3600,60*power(2,least(v_attempts-1,6)))::integer) end,
    updated_at=now() where kind=p_kind and order_id=p_order_id;
  return v_status;
end $function$

CREATE OR REPLACE FUNCTION public.finish_play_price_sync(p_price numeric, p_lease uuid, p_sku text, p_option text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform 1 from public.play_price_sync where price_inr=p_price and lease_id=p_lease
    and candidate_sku=p_sku and purchase_option_id=p_option and status='running' and lease_until>now() for update;
  if not found then return false; end if;
  if not exists(select 1 from public.products p where p.price=p_price
    and public.play_notes_product_eligible(p)) then return false; end if;
  update public.play_price_tiers set active=false where price_inr=p_price and play_sku<>p_sku and active;
  insert into public.play_price_tiers(price_inr,play_sku,active,purchase_option_id,currency_code,region_code,verified_at)
    values(p_price,p_sku,true,p_option,'INR','IN',now())
    on conflict(play_sku) do update set active=true,purchase_option_id=excluded.purchase_option_id,
      currency_code='INR',region_code='IN',verified_at=now();
  update public.play_price_sync set status='ready',lease_id=null,lease_until=null,last_error=null,
    last_synced_at=now(),updated_at=now() where price_inr=p_price;
  insert into public.play_price_sync_logs(price_inr,play_sku,event) values(p_price,p_sku,'verified');
  return true;
end; $function$

CREATE OR REPLACE FUNCTION public.finish_play_recovery_cursor(p_lease_id uuid, p_success boolean, p_next_page_token text DEFAULT NULL::text, p_error text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v public.play_recovery_cursor%rowtype;
begin
  select * into v from public.play_recovery_cursor where id=true and lease_id=p_lease_id
    and lease_until>now() for update;
  if not found then return 'lease_lost'; end if;
  if p_success then
    update public.play_recovery_cursor set
      start_time_ms=case when p_next_page_token is null then greatest(v.start_time_ms,v.end_time_ms-3600000) else v.start_time_ms end,
      end_time_ms=case when p_next_page_token is null then (extract(epoch from now())*1000)::bigint else v.end_time_ms end,
      next_page_token=p_next_page_token,lease_id=null,lease_until=null,attempts=0,
      next_attempt_at=now(),last_error=null,updated_at=now() where id=true;
    return 'done';
  end if;
  update public.play_recovery_cursor set lease_id=null,lease_until=null,attempts=v.attempts+1,
    next_attempt_at=now()+make_interval(secs=>least(3600,60*power(2,least(v.attempts,6)))::integer),
    last_error=left(coalesce(p_error,'failed'),300),updated_at=now() where id=true;
  return 'retry';
end $function$

CREATE OR REPLACE FUNCTION public.generate_unique_referral_code(p_length integer DEFAULT 7)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  -- Uppercase, unambiguous charset: excludes 0/O, 1/I/L. 31 symbols.
  v_charset constant text := '23456789ABCDEFGHJKMNPQRSTUVWXYZ';
  v_code text;
  v_attempt int := 0;
  v_byte int;
begin
  loop
    v_attempt := v_attempt + 1;
    v_code := '';
    while length(v_code) < p_length loop
      -- gen_random_uuid() is the database's cryptographic generator; byte 0 of a v4 uuid
      -- is fully random. 248 = 31 * 8, so rejecting >= 248 leaves no modulo bias.
      v_byte := get_byte(uuid_send(gen_random_uuid()), 0);
      if v_byte < 248 then
        v_code := v_code || substr(v_charset, 1 + (v_byte % 31), 1);
      end if;
    end loop;
    exit when not exists (select 1 from public.profiles where referral_code = v_code);
    if v_attempt > 30 then
      raise exception 'Could not generate a unique referral code after % attempts', v_attempt;
    end if;
  end loop;
  return v_code;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_my_play_fulfillment(p_order_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare o public.orders%rowtype;
begin
  select * into o from public.orders where id=p_order_id and user_id=auth.uid() and provider='play';
  if not found then return jsonb_build_object('success',false,'pending',true); end if;
  if o.status='refunded' then
    return jsonb_build_object('success',false,'pending',false,'message','This payment was refunded.'); end if;
  if exists(select 1 from public.purchases where order_id=o.id and status='duplicate') then
    return jsonb_build_object('success',false,'pending',false,'message','This product was already owned; contact support for a refund.'); end if;
  if public.play_entitlement_committed(o.id,o.purchase_token) then
    return jsonb_build_object('success',true,'internalOrderId',o.id,'amount',o.amount); end if;
  return jsonb_build_object('success',false,'pending',true);
end $function$

CREATE OR REPLACE FUNCTION public.get_my_wallet()
 RETURNS TABLE(available numeric, pending numeric, total_earned numeric, next_available_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  perform public.release_due_wallet_credits(auth.uid());
  return query select * from public.wallet_balance_of(auth.uid());
end;
$function$

CREATE OR REPLACE FUNCTION public.handle_payment_dispute(p_razorpay_payment_id text, p_outcome text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_order public.orders%rowtype;
  v_uid uuid;
  v_n integer := 0;
begin
  if p_outcome not in ('opened', 'won', 'lost') then
    raise exception 'handle_payment_dispute: unknown outcome %', p_outcome;
  end if;

  if p_outcome = 'lost' then
    return public.reverse_payment(p_razorpay_payment_id, 'chargeback', false)
           || jsonb_build_object('dispute', 'lost');
  end if;

  select user_id into v_uid from public.orders where razorpay_payment_id = p_razorpay_payment_id;
  if v_uid is not null then
    perform pg_advisory_xact_lock(hashtextextended('wallet:' || v_uid::text, 0));
  end if;
  select * into v_order from public.orders where razorpay_payment_id = p_razorpay_payment_id for update;
  if not found then return jsonb_build_object('status', 'unknown_payment'); end if;

  if p_outcome = 'opened' then
    update public.purchases set status = 'disputed' where order_id = v_order.id and status = 'success';
    get diagnostics v_n = row_count;
    return jsonb_build_object('status', case when v_n > 0 then 'access_suspended' else 'nothing_to_suspend' end,
                              'purchases_suspended', v_n);
  end if;

  -- won: restore, unless the student bought the same product again meanwhile
  -- (then this one is the duplicate; it keeps no access of its own).
  update public.purchases pu
     set status = case when exists (select 1 from public.purchases o
                                     where o.user_id = pu.user_id and o.product_id = pu.product_id
                                       and o.id <> pu.id and o.status = 'success')
                       then 'duplicate' else 'success' end
   where pu.order_id = v_order.id and pu.status = 'disputed';
  get diagnostics v_n = row_count;
  return jsonb_build_object('status', case when v_n > 0 then 'access_restored' else 'nothing_to_restore' end,
                            'purchases_restored', v_n);
end;
$function$

CREATE OR REPLACE FUNCTION public.handle_payment_refund(p_razorpay_payment_id text, p_full_refund boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not exists (select 1 from public.orders where razorpay_payment_id = p_razorpay_payment_id) then
    return jsonb_build_object('status', 'unknown_payment');
  end if;
  if not coalesce(p_full_refund, false) then
    return jsonb_build_object('status', 'partial_refund_ignored');
  end if;
  return public.reverse_payment(p_razorpay_payment_id, 'refunded', true);
end;
$function$

CREATE OR REPLACE FUNCTION public.identity_hash(p_kind text, p_value text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare
  v text;
  v_at int;
  v_local text;
  v_dom text;
begin
  if p_value is null or btrim(p_value) = '' then return null; end if;
  if p_kind = 'phone' then
    v := public.normalize_phone(p_value);
  elsif p_kind = 'email' then
    v := lower(btrim(p_value));
    v_at := position('@' in v);
    if v_at < 2 then return null; end if;
    v_local := split_part(substr(v, 1, v_at - 1), '+', 1);     -- name+anything@ == name@
    v_dom := substr(v, v_at + 1);
    if v_dom in ('gmail.com', 'googlemail.com') then
      v_local := replace(v_local, '.', '');                    -- a.b@gmail.com == ab@gmail.com
      v_dom := 'gmail.com';
    end if;
    if v_local = '' then return null; end if;
    v := v_local || '@' || v_dom;
  else
    raise exception 'identity_hash: unknown kind %', p_kind;
  end if;
  if v is null then return null; end if;
  return encode(sha256(convert_to('ayurpulse-identity-v1|' || p_kind || '|' || v, 'UTF8')), 'hex');
end;
$function$

CREATE OR REPLACE FUNCTION public.log_referral_settings_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_old jsonb := '{}'::jsonb;
  v_new jsonb := '{}'::jsonb;
  v_key text;
  v_o   jsonb := to_jsonb(old) - 'updated_at';
  v_n   jsonb := to_jsonb(new) - 'updated_at';
begin
  for v_key in select jsonb_object_keys(v_n) loop
    if v_o -> v_key is distinct from v_n -> v_key then
      v_old := v_old || jsonb_build_object(v_key, v_o -> v_key);
      v_new := v_new || jsonb_build_object(v_key, v_n -> v_key);
    end if;
  end loop;

  if v_new = '{}'::jsonb then
    return new; -- nothing but updated_at changed
  end if;

  insert into public.referral_settings_audit (changed_by, changed_by_email, old_values, new_values)
  values (auth.uid(), nullif(auth.jwt() ->> 'email', ''), v_old, v_new);
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.nonplay_test_attach_order(p_user uuid, p_order uuid, p_provider text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare o public.nonplay_test_orders%rowtype;
begin
  select * into strict o from public.nonplay_test_orders where id=p_order and user_id=p_user for update;
  if not public.nonplay_test_product_allowed(p_user,o.product_id) or p_provider !~ '^order_[A-Za-z0-9]+$'
    or o.status not in ('pending','created') or o.expires_at<=now() then raise exception 'test order unavailable'; end if;
  if o.razorpay_order_id is not null and o.razorpay_order_id<>p_provider then raise exception 'provider binding conflict'; end if;
  update public.nonplay_test_orders set razorpay_order_id=p_provider,status='created' where id=o.id returning * into o;
  update public.nonplay_test_checkouts set state='open',updated_at=now() where order_id=o.id and state='pending';
  insert into public.nonplay_test_audit(order_id,event) values(o.id,'attached');
  return to_jsonb(o);
end $function$

CREATE OR REPLACE FUNCTION public.nonplay_test_observe_payment(p_order uuid, p_payment text, p_status text, p_amount integer, p_currency text, p_provider text, p_created timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare o public.nonplay_test_orders%rowtype; a public.nonplay_test_attempts%rowtype; e public.nonplay_test_entitlements%rowtype;
begin
  select * into strict o from public.nonplay_test_orders where id=p_order for update;
  if not public.nonplay_test_product_allowed(o.user_id,o.product_id) or p_amount is distinct from o.amount_paise
    or p_currency is distinct from 'INR' or p_provider is distinct from o.razorpay_order_id
    or p_payment is null or p_payment !~ '^pay_[A-Za-z0-9]+$'
    or p_status is null or p_status not in ('created','authorized','captured','failed','refunded')
    or p_created is null or p_created<o.created_at-interval '60 seconds' or p_created>now()+interval '60 seconds' then
    raise exception 'provider facts do not match test order'; end if;
  select * into a from public.nonplay_test_attempts where payment_id=p_payment for update;
  if found and a.order_id<>o.id then raise exception 'payment ownership conflict'; end if;
  insert into public.nonplay_test_attempts(payment_id,order_id,status,amount_paise) values(p_payment,o.id,p_status,p_amount)
    on conflict(payment_id) do update set status=case
      when nonplay_test_attempts.status='refunded' then 'refunded'
      when nonplay_test_attempts.status='captured' and excluded.status<>'refunded' then 'captured'
      else excluded.status end,observed_at=now() returning * into a;
  insert into public.nonplay_test_audit(order_id,event) values(o.id,a.status);
  if a.status='refunded' then
    update public.nonplay_test_entitlements set revoked_at=coalesce(revoked_at,now()) where order_id=o.id and payment_id=p_payment;
    if not exists(select 1 from public.nonplay_test_entitlements where order_id=o.id and payment_id<>p_payment and revoked_at is null) then
      update public.nonplay_test_orders set status='reversed' where id=o.id;
      update public.nonplay_test_checkouts set state='reversed',updated_at=now() where order_id=o.id;
    end if;
  elsif a.status='captured' and p_created<=o.expires_at and o.status<>'reversed' then
    insert into public.nonplay_test_entitlements(user_id,product_id,order_id,payment_id)
      values(o.user_id,o.product_id,o.id,p_payment) on conflict(user_id,product_id) do nothing;
    select * into e from public.nonplay_test_entitlements where user_id=o.user_id and product_id=o.product_id;
    if e.order_id=o.id and e.payment_id=p_payment and e.revoked_at is null then
      update public.nonplay_test_orders set status='paid' where id=o.id;
      update public.nonplay_test_checkouts set state='complete',updated_at=now() where order_id=o.id;
      return jsonb_build_object('success',true,'orderId',o.id,'amount',o.amount_paise/100.0);
    end if;
    return jsonb_build_object('success',false,'pending',false,'message','A different test capture already fulfilled this product.');
  end if;
  select * into e from public.nonplay_test_entitlements where order_id=o.id and revoked_at is null;
  if found and o.status<>'reversed' then return jsonb_build_object('success',true,'orderId',o.id,'amount',o.amount_paise/100.0); end if;
  return jsonb_build_object('success',false,'pending',a.status in ('created','authorized') and now()<o.expires_at,
    'message',case when a.status='failed' then 'Test payment failed.' when a.status='refunded' then 'Test payment reversed.' else 'Test payment is not captured.' end);
end $function$

CREATE OR REPLACE FUNCTION public.nonplay_test_prepare_order(p_user uuid, p_product text, p_key uuid, p_key_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare o public.nonplay_test_orders%rowtype; t public.nonplay_test_products%rowtype; claimed boolean:=false;
begin
  if not public.nonplay_test_product_allowed(p_user,p_product) or p_key is null or p_key_id !~ '^rzp_test_[A-Za-z0-9]+$' then
    raise exception 'test checkout unavailable' using errcode='42501'; end if;
  perform pg_advisory_xact_lock(hashtextextended('nonplay_test:'||p_user::text,0));
  select * into o from public.nonplay_test_orders where user_id=p_user and idempotency_key=p_key for update;
  if found and (o.product_id<>p_product or o.key_id<>p_key_id) then raise exception 'idempotency conflict'; end if;
  if o.id is null then
    update public.nonplay_test_orders set status='expired' where user_id=p_user and product_id=p_product
      and status in ('pending','created') and expires_at<=now();
    select * into o from public.nonplay_test_orders where user_id=p_user and product_id=p_product
      and status in ('pending','created') for update;
  end if;
  if o.id is null then
    if exists(select 1 from public.nonplay_test_entitlements where user_id=p_user and product_id=p_product) then
      raise exception 'test product already fulfilled; reconcile existing entitlement'; end if;
    select * into strict t from public.nonplay_test_products where id=p_product;
    insert into public.nonplay_test_orders(user_id,product_id,idempotency_key,key_id,amount_paise,title)
      values(p_user,p_product,p_key,p_key_id,t.price_paise,t.title) returning * into o;
    insert into public.nonplay_test_checkouts(order_id) values(o.id);
    insert into public.nonplay_test_audit(order_id,event) values(o.id,'reserved');
    claimed:=true;
  end if;
  if o.key_id<>p_key_id then raise exception 'test credential rotation requires reconciliation'; end if;
  return to_jsonb(o)||jsonb_build_object('claimed',claimed);
end $function$

CREATE OR REPLACE FUNCTION public.nonplay_test_quote(p_user uuid, p_product text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare t public.nonplay_test_products%rowtype;
begin
  if not public.nonplay_test_product_allowed(p_user,p_product) then raise exception 'test checkout unavailable' using errcode='42501'; end if;
  select * into strict t from public.nonplay_test_products where id=p_product;
  return jsonb_build_object('ok',true,'listPrice',t.price_paise/100.0,'amount',t.price_paise/100.0,
    'referralDiscount',0,'walletEligible',false,'walletAvailable',0,'walletMaxUsable',0,'walletAmount',0);
end $function$

CREATE OR REPLACE FUNCTION public.notes_derive_course()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_course_id text;
  v_year_id text;
begin
  select course_id, year_id into v_course_id, v_year_id from public.chapters where id = new.chapter_id;
  if v_course_id is null then
    raise exception 'Unknown chapter_id % on notes', new.chapter_id;
  end if;
  if new.course_id is null then
    new.course_id := v_course_id;
  elsif new.course_id is distinct from v_course_id then
    raise exception 'notes.course_id (%) does not match its chapter''s course (%)', new.course_id, v_course_id;
  end if;
  if new.year_id is null then
    new.year_id := v_year_id;
  elsif new.year_id is distinct from v_year_id then
    raise exception 'notes.year_id (%) does not match its chapter''s year (%)', new.year_id, v_year_id;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.orders_derive_course()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_course_id text;
begin
  if auth.uid() is not null and new.status='paid'
     and (tg_op='INSERT' or old.status is distinct from 'paid')
     and not public.am_i_admin() then
    raise exception 'Orders can only be marked paid by the payment system';
  end if;
  if tg_op='UPDATE' then return new; end if;
  select course_id into v_course_id from public.products where id=new.product_id;
  if v_course_id is null then raise exception 'Unknown product_id % on orders',new.product_id; end if;
  if new.course_id is null then new.course_id:=v_course_id;
  elsif new.course_id is distinct from v_course_id then
    raise exception 'orders.course_id (%) does not match product course (%)',new.course_id,v_course_id;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.orders_entitlement_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if row(new.scope,new.chapter_id,new.subject_id,new.year_id,new.year_ids,new.course_id)
     is distinct from row(old.scope,old.chapter_id,old.subject_id,old.year_id,old.year_ids,old.course_id) then
    raise exception 'orders entitlement snapshot is immutable' using errcode='42501';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.orders_guard_client_writes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_p public.products%rowtype;
begin
  -- SECURITY DEFINER so the product lookup below is not filtered by the
  -- student's RLS. The caller is identified by the session `role` setting
  -- (PostgREST does SET LOCAL ROLE anon|authenticated|service_role), which
  -- is not changed by definer functions; migrations/psql report 'none'. The
  -- app.trusted_order_write flag is set only by delete_my_account() (above).
  if coalesce(current_setting('role', true), 'none') not in ('anon', 'authenticated')
     or coalesce(current_setting('app.trusted_order_write', true), 'false') = 'true'
     or public.am_i_admin() then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.status is distinct from 'created' then
      raise exception 'Orders can only be created with status created';
    end if;
    select * into v_p from public.products where id = new.product_id;
    if not found or not v_p.active then
      raise exception 'This product is not available';
    end if;
    -- Never trust client-written money or scope: derive it from the product.
    new.razorpay_order_id := null;
    new.razorpay_payment_id := null;
    new.amount := v_p.price;
    new.scope := v_p.scope;
    new.chapter_id := v_p.chapter_id;
    new.subject_id := v_p.subject_id;
    new.year_id := v_p.year_id;
    new.year_ids := v_p.year_ids;
    new.course_id := v_p.course_id;
    return new;
  end if;

  -- UPDATE by a student: only status may change (and updated_at).
  if (to_jsonb(new) - 'status' - 'updated_at') is distinct from (to_jsonb(old) - 'status' - 'updated_at') then
    raise exception 'Orders cannot be edited';
  end if;
  if new.status is distinct from old.status then
    if old.status is distinct from 'created' or new.status not in ('cancelled', 'failed') then
      raise exception 'Order status can only be changed by the payment system';
    end if;
    if old.razorpay_payment_id is not null
       or exists (select 1 from public.payments p where p.order_id = old.id) then
      raise exception 'Order status can only be changed by the payment system';
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.orders_immutable_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.amount is distinct from old.amount then raise exception 'orders.amount is immutable' using errcode='42501'; end if;
  if old.razorpay_order_id is not null and new.razorpay_order_id is distinct from old.razorpay_order_id then raise exception 'orders.razorpay_order_id is immutable' using errcode='42501'; end if;
  if new.user_id is distinct from old.user_id and new.user_id is not null then raise exception 'orders.user_id is immutable' using errcode='42501'; end if;
  if new.product_id is distinct from old.product_id and new.product_id is not null then raise exception 'orders.product_id is immutable' using errcode='42501'; end if;
  if new.list_price is distinct from old.list_price or new.referral_discount is distinct from old.referral_discount or new.wallet_amount is distinct from old.wallet_amount then raise exception 'orders price breakdown is immutable' using errcode='42501'; end if;
  if new.referral_id is distinct from old.referral_id and new.referral_id is not null then raise exception 'orders.referral_id is immutable' using errcode='42501'; end if;
  if new.expires_at is distinct from old.expires_at then raise exception 'orders.expires_at is immutable' using errcode='42501'; end if;
  if new.provider is distinct from old.provider or (old.play_sku is not null and new.play_sku is distinct from old.play_sku) then raise exception 'orders provider/SKU is immutable' using errcode='42501'; end if;
  if old.purchase_token is not null and new.purchase_token is distinct from old.purchase_token then raise exception 'orders.purchase_token is immutable' using errcode='42501'; end if;
  if old.external_transaction_id is not null and new.external_transaction_id is distinct from old.external_transaction_id then raise exception 'orders.external_transaction_id is immutable' using errcode='42501'; end if;
  if new.gst_rate_percent is distinct from old.gst_rate_percent or new.tax_pre_amount is distinct from old.tax_pre_amount
     or new.tax_amount is distinct from old.tax_amount then raise exception 'orders tax snapshot is immutable' using errcode='42501'; end if;
  if (old.tax_region_code is not null and new.tax_region_code is distinct from old.tax_region_code)
     or (old.tax_administrative_area is not null and new.tax_administrative_area is distinct from old.tax_administrative_area)
     then raise exception 'orders buyer tax address is immutable' using errcode='42501'; end if;
  if old.external_choice_bound_order_id is not null and new.external_choice_bound_order_id is distinct from old.external_choice_bound_order_id then raise exception 'orders.external_choice_bound_order_id is immutable' using errcode='42501'; end if;
  -- Token may move exactly once from a cancelled choice order to its Razorpay order.
  if old.external_transaction_token is not null and new.external_transaction_token is distinct from old.external_transaction_token
     and not (old.provider = 'play' and new.external_transaction_token is null and old.status = 'cancelled') then
    raise exception 'orders.external_transaction_token is immutable' using errcode='42501';
  end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.orders_snapshot_tax()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_rate_text text; v_rate numeric(6,2);
begin
  select value into v_rate_text from public.app_config where key='gst_rate_percent';
  if v_rate_text is null or v_rate_text !~ '^[0-9]+(\.[0-9]{1,2})?$' then
    raise exception 'GST rate configuration unavailable';
  end if;
  v_rate:=v_rate_text::numeric;
  if v_rate<0 or v_rate>100 then raise exception 'GST rate out of range'; end if;
  new.gst_rate_percent:=v_rate;
  new.tax_pre_amount:=round(new.amount/(1+v_rate/100),2);
  new.tax_amount:=new.amount-new.tax_pre_amount;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.play_purchase_entitlement_from_order()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
declare o public.orders%rowtype;
begin
  if new.order_id is null then return new; end if;
  select * into o from public.orders where id=new.order_id;
  if not found or o.provider<>'play' then return new; end if;
  if new.user_id is distinct from o.user_id or new.product_id is distinct from o.product_id
    or new.amount is distinct from o.amount or o.course_id is null
    or o.scope not in ('chapter','subject','year','bundle') or o.scope is null
    or (o.scope='chapter' and o.chapter_id is null)
    or (o.scope='subject' and o.subject_id is null)
    or (o.scope='year' and o.year_id is null)
    or (o.scope='bundle' and (coalesce(cardinality(o.year_ids),0)=0 or array_position(o.year_ids,null) is not null)) then
    raise exception 'Play purchase does not match order entitlement';
  end if;
  new.scope:=o.scope; new.chapter_id:=o.chapter_id; new.subject_id:=o.subject_id;
  new.year_id:=o.year_id; new.year_ids:=o.year_ids; new.course_id:=o.course_id;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.prepare_notes_choice_checkout(p_user_id uuid, p_choice_id text, p_product_id text, p_use_wallet boolean, p_buyer_state text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c public.orders%rowtype; a public.notes_choice_checkouts%rowtype;
  o public.orders%rowtype; p public.products%rowtype; priced jsonb;
begin
  if p_buyer_state is null or p_buyer_state <> all(array['ANDAMAN AND NICOBAR ISLANDS','ANDHRA PRADESH','ARUNACHAL PRADESH','ASSAM','BIHAR','CHANDIGARH','CHHATTISGARH','DADRA AND NAGAR HAVELI','DADRA AND NAGAR HAVELI AND DAMAN AND DIU','DAMAN AND DIU','DELHI','GOA','GUJARAT','HARYANA','HIMACHAL PRADESH','JAMMU AND KASHMIR','JHARKHAND','KARNATAKA','KERALA','LADAKH','LAKSHADWEEP','MADHYA PRADESH','MAHARASHTRA','MANIPUR','MEGHALAYA','MIZORAM','NAGALAND','ODISHA','PUDUCHERRY','PUNJAB','RAJASTHAN','SIKKIM','TAMIL NADU','TELANGANA','TRIPURA','UTTAR PRADESH','UTTARAKHAND','WEST BENGAL']) then return jsonb_build_object('ok',false,'code','buyer_state_invalid'); end if;
  perform pg_advisory_xact_lock(hashtextextended('wallet:' || p_user_id::text,0));
  select * into c from public.orders where id=p_choice_id for update;
  if not found or c.user_id is distinct from p_user_id or c.product_id is distinct from p_product_id
      or c.provider<>'play' or c.purchase_token is not null or c.play_sku is null then
    return jsonb_build_object('ok',false,'code','choice_unavailable');
  end if;
  if not exists(select 1 from public.profiles where id=p_user_id and not blocked) then
    return jsonb_build_object('ok',false,'code','account_unavailable');
  end if;
  select * into p from public.products where id=p_product_id and active;
  if not found or ((p.scope='bundle' and p.product_type='notes_bundle')
      or (p.scope in ('chapter','subject','year') and p.product_type='notes')) is not true then
    return jsonb_build_object('ok',false,'code','notes_unavailable');
  end if;
  select * into a from public.notes_choice_checkouts where choice_id=p_choice_id;
  if found then
    if a.use_wallet is distinct from p_use_wallet or a.buyer_state is distinct from p_buyer_state then
      return jsonb_build_object('ok',false,'code','choice_parameters_changed');
    end if;
    select * into o from public.orders where id=a.order_id;
    if o.user_id is distinct from p_user_id or o.product_id is distinct from p_product_id
        or o.status<>'created' or o.expires_at<=now() then
      return jsonb_build_object('ok',false,'code','checkout_expired');
    end if;
    return jsonb_build_object('ok',true,'claimed',false,'order_id',o.id,'state',a.state);
  end if;
  if c.status<>'created' or c.external_transaction_token is null
      or c.external_choice_bound_order_id is not null or c.expires_at is null or c.expires_at<=now() then
    return jsonb_build_object('ok',false,'code','choice_expired');
  end if;
  -- Same authoritative pricing, friend discount and wallet reservations as web.
  priced:=public.create_priced_order(p_user_id,p_product_id,p_use_wallet);
  if not coalesce((priced->>'ok')::boolean,false) then return priced; end if;
  select * into o from public.orders where id=priced->>'order_id' for update;
  if o.provider<>'razorpay' or o.user_id is distinct from p_user_id
      or o.product_id is distinct from p_product_id or o.tax_pre_amount is null
      or o.tax_amount is null or o.gst_rate_percent is null
      or o.tax_pre_amount+o.tax_amount<>o.amount then raise exception 'Invalid priced Notes order'; end if;
  -- Explicitly cancel even if the pricing implementation changes in the future.
  update public.orders set status='cancelled' where id=c.id and status='created';
  update public.orders set external_transaction_token=null,external_choice_bound_order_id=o.id where id=c.id;
  update public.orders set external_transaction_token=c.external_transaction_token,
    external_transaction_id='medveda_' || replace(o.id,'-',''),external_report_status='pending',
    play_sku=c.play_sku,tax_region_code='IN',tax_administrative_area=p_buyer_state where id=o.id;
  insert into public.notes_choice_checkouts(choice_id,order_id,use_wallet,buyer_state)
    values(c.id,o.id,p_use_wallet,p_buyer_state);
  return jsonb_build_object('ok',true,'claimed',true,'state','creating','order_id',o.id);
end $function$

CREATE OR REPLACE FUNCTION public.products_derive_course()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_course_id text;
  v_matched_years integer;
  v_distinct_courses integer;
begin
  if new.scope = 'chapter' then
    if new.chapter_id is null then
      raise exception 'products.chapter_id is required for scope=chapter';
    end if;
    select course_id into v_course_id from public.chapters where id = new.chapter_id;
    if v_course_id is null then
      raise exception 'Unknown chapter_id % on products', new.chapter_id;
    end if;

  elsif new.scope = 'subject' then
    if new.subject_id is null then
      raise exception 'products.subject_id is required for scope=subject';
    end if;
    select course_id into v_course_id from public.subjects where id = new.subject_id;
    if v_course_id is null then
      raise exception 'Unknown subject_id % on products', new.subject_id;
    end if;

  elsif new.scope = 'year' then
    if new.year_id is null then
      raise exception 'products.year_id is required for scope=year';
    end if;
    select course_id into v_course_id from public.years where id = new.year_id;
    if v_course_id is null then
      raise exception 'Unknown year_id % on products', new.year_id;
    end if;

  elsif new.scope = 'bundle' then
    if new.year_ids is null or array_length(new.year_ids, 1) is null then
      raise exception 'products.year_ids is required and non-empty for scope=bundle';
    end if;

    select count(*), count(distinct y.course_id)
      into v_matched_years, v_distinct_courses
      from public.years y
      where y.id = any(new.year_ids);

    if v_matched_years <> array_length(new.year_ids, 1) then
      raise exception 'products.year_ids contains an unknown year id';
    end if;
    if v_distinct_courses <> 1 then
      raise exception 'products.year_ids must all belong to the same course (found % distinct courses)', v_distinct_courses;
    end if;

    select y.course_id into v_course_id from public.years y where y.id = new.year_ids[1];

  else
    raise exception 'Unknown product scope: %', new.scope;
  end if;

  if new.course_id is null then
    new.course_id := v_course_id;
  elsif new.course_id is distinct from v_course_id then
    raise exception 'products.course_id (%) does not match its content''s course (%)', new.course_id, v_course_id;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.profiles_before_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_year_course_id text;
  v_client boolean := coalesce(current_setting('role', true), 'none') in ('anon', 'authenticated');
  v_bypass boolean := coalesce(current_setting('app.allow_profile_admin_fields', true), 'false') = 'true';
  v_is_admin boolean := public.am_i_admin();
  v_protected text[] := array[
    'id', 'blocked', 'is_blocked', 'role', 'is_admin', 'is_staff', 'status',
    'email', 'email_verified', 'mobile_verified', 'referral_code', 'course_id', 'year_id',
    'created_at'
  ];
  v_old jsonb;
  v_new jsonb;
  v_col text;
begin
  if v_client and not v_bypass and not v_is_admin then
    if tg_op = 'UPDATE' then
      v_old := to_jsonb(old);
      v_new := to_jsonb(new);
      foreach v_col in array v_protected loop
        if v_new -> v_col is distinct from v_old -> v_col then
          raise exception 'Cannot modify protected profile field "%"', v_col
            using errcode = '42501';
        end if;
      end loop;
      -- The phone is only changeable through change_my_phone() (rate limited, generic
      -- errors). Compared normalised, so re-saving the same number is not a change.
      if public.normalize_phone(new.phone) is distinct from public.normalize_phone(old.phone)
         or new.phone_normalized is distinct from old.phone_normalized then
        raise exception 'Use change_my_phone() to change the phone number'
          using errcode = '42501';
      end if;
    else
      -- A client-created profile row starts unblocked and unverified.
      new.blocked := false;
      new.email_verified := false;
      new.mobile_verified := false;
    end if;
  end if;

  -- Self-heal: if year_id no longer belongs to course_id, clear it.
  if new.year_id is not null then
    select course_id into v_year_course_id from public.years where id = new.year_id;
    if v_year_course_id is null or v_year_course_id is distinct from new.course_id then
      new.year_id := null;
    end if;
  end if;

  return new;
end;
$function$

