CREATE OR REPLACE FUNCTION public.quote_my_order_legacy(p_product_id text, p_use_wallet boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid      uuid := auth.uid();
  v_set      public.referral_settings%rowtype;
  v_product  public.products%rowtype;
  v_price    numeric(10, 2);
  v_discount numeric(10, 2) := 0;
  v_wallet   numeric(10, 2) := 0;
  v_avail    numeric(10, 2) := 0;
  v_cap      numeric(10, 2) := 0;
  v_eligible boolean := false;
begin
  if v_uid is null then raise exception 'not authenticated' using errcode = '42501'; end if;
  select * into v_product from public.products where id = p_product_id and active;
  if not found then return jsonb_build_object('ok', false, 'code', 'product_unavailable'); end if;
  if exists (select 1 from public.purchases
              where user_id = v_uid and product_id = v_product.id and status = 'success') then
    return jsonb_build_object('ok', false, 'code', 'already_owned');
  end if;
  v_price := v_product.price::numeric(10, 2);
  select * into v_set from public.referral_settings where id = true;

  if v_set.enabled and v_set.friend_discount_percent > 0
     and exists (select 1 from public.referrals r
                   join public.profiles rp on rp.id = r.referrer_id and not rp.blocked
                  where r.referred_id = v_uid and r.status in ('pending', 'qualified') and r.first_order_id is null)
     and not exists (select 1 from public.purchases pu where pu.user_id = v_uid and pu.status = 'success')
     and not public.has_prior_purchase_identity(v_uid) then
    v_discount := round(v_price * v_set.friend_discount_percent / 100, 2);
    if v_set.friend_discount_max is not null then v_discount := least(v_discount, v_set.friend_discount_max); end if;
    v_discount := greatest(0, least(v_discount, v_price - 1));
  end if;

  -- Program off: nothing is wallet-eligible, so the balance can be neither shown nor spent.
  v_eligible := v_set.enabled and v_product.product_type = any (v_set.wallet_product_types);
  if v_eligible then
    perform public.release_due_wallet_credits(v_uid);
    select available into v_avail from public.wallet_balance_of(v_uid);
    v_cap := floor((v_price - v_discount) * v_set.wallet_max_percent) / 100;
    if p_use_wallet then v_wallet := greatest(0, least(v_cap, coalesce(v_avail, 0))); end if;
  end if;

  return jsonb_build_object(
    'ok', true, 'list_price', v_price, 'referral_discount', v_discount,
    'wallet_eligible', v_eligible, 'wallet_available', coalesce(v_avail, 0),
    'wallet_max_usable', least(v_cap, coalesce(v_avail, 0)),
    'wallet_amount', v_wallet, 'amount', v_price - v_discount - v_wallet
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.rate_limit_hit(p_key text, p_limit integer, p_window_seconds integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_window timestamptz :=
    to_timestamp(floor(extract(epoch from now()) / p_window_seconds) * p_window_seconds);
  v_hits integer;
begin
  if p_key is null or p_limit <= 0 or p_window_seconds <= 0 then
    raise exception 'invalid rate limit parameters';
  end if;

  insert into public.rate_limits (key, window_start, hits)
  values (p_key, v_window, 1)
  on conflict (key, window_start) do update set hits = public.rate_limits.hits + 1
  returning hits into v_hits;

  -- opportunistic cleanup of old windows (cheap; keeps the table tiny)
  if random() < 0.02 then
    delete from public.rate_limits where window_start < now() - interval '1 day';
  end if;

  return v_hits <= p_limit;
end;
$function$

CREATE OR REPLACE FUNCTION public.razorpay_purchase_entitlement_from_order()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_order public.orders%rowtype;
begin
  if new.order_id is null then return new; end if;
  select * into v_order from public.orders where id=new.order_id;
  if not found or v_order.provider<>'razorpay' then return new; end if;
  if new.user_id is distinct from v_order.user_id
     or new.product_id is distinct from v_order.product_id
     or new.amount is distinct from v_order.amount
     or v_order.scope is null or v_order.scope not in ('chapter','subject','year','bundle') then
    raise exception 'Razorpay purchase does not match order entitlement';
  end if;
  new.scope:=v_order.scope;
  new.chapter_id:=v_order.chapter_id;
  new.subject_id:=v_order.subject_id;
  new.year_id:=v_order.year_id;
  new.year_ids:=v_order.year_ids;
  new.course_id:=v_order.course_id;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.record_notes_choice_authorization(p_order_id text, p_provider_time timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare o public.orders%rowtype;
begin
  select * into o from public.orders where id=p_order_id for update;
  if not found or o.provider<>'razorpay' or o.external_transaction_token is null then return; end if;
  if p_provider_time is null or p_provider_time>now()+interval '5 minutes' then
    raise exception 'Invalid provider authorisation time'; end if;
  update public.orders set ucb_transaction_time=coalesce(ucb_transaction_time,p_provider_time)
    where id=o.id;
  insert into public.payment_jobs(kind,target_id,deadline_at)
    values('reports',o.id,coalesce(o.ucb_transaction_time,p_provider_time)+interval '24 hours')
    on conflict(kind,target_id) do nothing;
end $function$

CREATE OR REPLACE FUNCTION public.record_payment_capture(p_payment_id text, p_razorpay_order_id text, p_amount_paise bigint, p_provider_time timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_order_id text; v_capture public.payment_captures%rowtype;
begin
  if p_payment_id is null or p_razorpay_order_id is null or p_amount_paise is null or p_amount_paise<=0
    then raise exception 'invalid capture'; end if;
  select id into v_order_id from public.orders where razorpay_order_id=p_razorpay_order_id;
  insert into public.payment_captures(payment_id,razorpay_order_id,order_id,amount_paise,provider_time)
  values(p_payment_id,p_razorpay_order_id,v_order_id,p_amount_paise,p_provider_time)
  on conflict(payment_id) do update set provider_time=coalesce(public.payment_captures.provider_time,excluded.provider_time),
    order_id=coalesce(public.payment_captures.order_id,excluded.order_id);
  select * into v_capture from public.payment_captures where payment_id=p_payment_id;
  if v_capture.razorpay_order_id<>p_razorpay_order_id or v_capture.amount_paise<>p_amount_paise
    then raise exception 'capture identity mismatch'; end if;
