CREATE OR REPLACE FUNCTION public.register_push_token(p_token text, p_platform text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'Not authenticated' using errcode = '28000'; end if;
  if p_token is null or p_token !~ '^Expo(nent)?PushToken\[[A-Za-z0-9_-]{10,}\]$' then
    raise exception 'Invalid push token' using errcode = '22023';
  end if;
  if p_platform is null or p_platform not in ('ios', 'android', 'web') then
    raise exception 'Invalid platform' using errcode = '22023';
  end if;
  if not public.rate_limit_hit('push-register:' || v_uid::text, 30, 3600) then
    raise exception 'Too many requests' using errcode = '54000';
  end if;

  insert into public.push_tokens (user_id, expo_push_token, platform, updated_at)
  values (v_uid, p_token, p_platform, now())
  on conflict (expo_push_token) do update
    set user_id = excluded.user_id, platform = excluded.platform, updated_at = now();

  -- keep only this user's 10 most recent devices
  delete from public.push_tokens
  where user_id = v_uid
    and id not in (select id from public.push_tokens where user_id = v_uid order by updated_at desc limit 10);
end $function$

CREATE OR REPLACE FUNCTION public.reserve_note_pdf_validation(p_request_id uuid, p_admin uuid, p_hash text, p_bytes bigint, p_url text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare u public.note_upload_requests%rowtype; v_path text;
begin
  v_path := 'validated/' || p_admin || '/' || p_request_id || '.pdf';
  insert into public.note_upload_requests(request_id,admin_user_id,sha256,object_path,pdf_url)
    values(p_request_id,p_admin,p_hash,v_path,p_url) on conflict(request_id) do nothing;
  select * into u from public.note_upload_requests where request_id=p_request_id for update;
  if u.admin_user_id<>p_admin or u.sha256<>p_hash or u.object_path<>v_path or u.pdf_url<>p_url then
    raise exception 'Request ID already used' using errcode='23505';
  end if;
  insert into public.note_pdf_validation_jobs(request_id,expected_bytes)
    values(p_request_id,p_bytes) on conflict(request_id) do nothing;
  if (select expected_bytes from public.note_pdf_validation_jobs where request_id=p_request_id)<>p_bytes then
    raise exception 'Request size changed' using errcode='23505';
  end if;
  -- Explicit same-file admin retry rearms exhausted transient failures only.
  update public.note_pdf_validation_jobs set status='pending',attempts=0,
    lease_id=null,lease_until=null,last_error=null,updated_at=now()
    where request_id=p_request_id and attempts>=5 and
      (status='pending' or (status='working' and lease_until<now()));
end $function$

CREATE OR REPLACE FUNCTION public.retry_play_price_sync(p_price numeric)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.am_i_admin() then raise exception 'Admin access required' using errcode='42501'; end if;
  if not exists(select 1 from public.products p where p.price=p_price
    and public.play_notes_product_eligible(p)) then return false; end if;
  update public.play_price_sync set status='pending', next_attempt_at=now(), last_error=null, updated_at=now()
    where price_inr=p_price and (lease_until is null or lease_until < now());
  if not found then return false; end if;
  insert into public.play_price_sync_logs(price_inr,play_sku,event,detail)
    select price_inr,candidate_sku,'queued','admin retry' from public.play_price_sync where price_inr=p_price;
  return true;
end; $function$

CREATE OR REPLACE FUNCTION public.reverse_payment(p_razorpay_payment_id text, p_purchase_status text, p_restore_wallet boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid;
  v_order public.orders%rowtype;
  v_credit public.wallet_ledger%rowtype;
  v_debit public.wallet_ledger%rowtype;
  v_restored numeric(10, 2) := 0;
  v_revoked integer := 0;
  v_rows integer := 0;
  v_avail numeric(10, 2);
  v_reversed numeric(10, 2);
  v_status jsonb;
begin
  if p_purchase_status not in ('refunded', 'chargeback') then
    raise exception 'reverse_payment: bad purchase status %', p_purchase_status;
  end if;

  -- Same lock order as settle_razorpay_payment (wallet lock, THEN the order row)
  -- so a refund cannot deadlock with a replayed capture event.
  select user_id into v_uid from public.orders where razorpay_payment_id = p_razorpay_payment_id;
  if v_uid is not null then
    perform pg_advisory_xact_lock(hashtextextended('wallet:' || v_uid::text, 0));
  end if;

  select * into v_order from public.orders where razorpay_payment_id = p_razorpay_payment_id for update;
  if not found then return jsonb_build_object('status', 'unknown_payment'); end if;

  -- ---- Take the access back ----------------------------------------------
  update public.orders set status = 'refunded', updated_at = now()
   where id = v_order.id and status = 'paid';

  update public.purchases set status = p_purchase_status
   where order_id = v_order.id and status not in ('refunded', 'chargeback');
  get diagnostics v_revoked = row_count;

  -- ---- Give the wallet amount this order used back to the student ---------
  if p_restore_wallet then
    select * into v_debit from public.wallet_ledger
     where order_id = v_order.id and entry_type = 'debit' and source = 'order_payment';
    if found and v_debit.user_id is not null then
      perform set_config('app.trusted_order_write', 'true', true);
      insert into public.wallet_ledger (user_id, entry_type, status, amount, source, order_id, note)
      values (v_debit.user_id, 'credit', 'available', v_debit.amount, 'order_refund', v_order.id,
              'Wallet amount restored after refund')
      on conflict (order_id) where entry_type = 'credit' and source = 'order_refund' do nothing;
      get diagnostics v_rows = row_count;   -- 1 on first insert, 0 on replay
      perform set_config('app.trusted_order_write', 'false', true);
      v_restored := case when v_rows > 0 then v_debit.amount else 0 end;
    end if;
  end if;

  -- ---- The referrer's credit for this friend's purchase --------------------
  -- Looked up by the ledger row's own order_id, NOT through referrals: the
  -- referrals row is deleted when the friend deletes their account.
  select * into v_credit from public.wallet_ledger
   where order_id = v_order.id and entry_type = 'credit' and source = 'referral_reward'
   for update;

  if not found then
    v_status := jsonb_build_object('status', 'no_referral_credit');

  elsif v_credit.status = 'cancelled' then
    v_status := jsonb_build_object('status', 'already_cancelled');

  elsif v_credit.status = 'pending' then
    -- Still held (even if the hold has technically run out but the release job
    -- has not run yet): cancel it.
    perform set_config('app.trusted_order_write', 'true', true);
    update public.wallet_ledger set status = 'cancelled' where id = v_credit.id;
    perform set_config('app.trusted_order_write', 'false', true);
    update public.referrals
       set status = 'rejected', reject_reason = 'friend_payment_reversed'
     where id = v_credit.referral_id and status <> 'rejected';
    v_status := jsonb_build_object('status', 'credit_cancelled', 'amount', v_credit.amount);

  elsif exists (select 1 from public.wallet_ledger
                 where entry_type = 'reversal' and reverses_id = v_credit.id) then
    v_status := jsonb_build_object('status', 'already_reversed', 'ledger_id', v_credit.id);

  elsif v_credit.user_id is null then
    v_status := jsonb_build_object('status', 'referrer_gone', 'ledger_id', v_credit.id);

  elsif v_credit.expires_at is not null and v_credit.expires_at <= now() then
    v_status := jsonb_build_object('status', 'credit_expired', 'ledger_id', v_credit.id);

  else
    -- Released ('available'): reverse it with a ledger row, but never by more
    -- than the referrer still has (the ledger refuses to overdraw). What cannot
    -- be recovered is flagged for a manual decision.
    perform pg_advisory_xact_lock(hashtextextended('wallet:' || v_credit.user_id::text, 0));
    select available into v_avail from public.wallet_balance_of(v_credit.user_id);
    v_reversed := least(v_credit.amount, coalesce(v_avail, 0));
    if v_reversed > 0 then
      perform set_config('app.trusted_order_write', 'true', true);
      insert into public.wallet_ledger (user_id, entry_type, status, amount, source, reverses_id, referral_id, order_id, note)
      values (v_credit.user_id, 'reversal', 'available', v_reversed, 'order_refund', v_credit.id, v_credit.referral_id, v_order.id,
              'Friend''s payment was reversed')
      on conflict (reverses_id) where entry_type = 'reversal' do nothing;
      perform set_config('app.trusted_order_write', 'false', true);
    end if;
    update public.referrals
       set status = 'rejected', reject_reason = 'friend_payment_reversed'
     where id = v_credit.referral_id and status <> 'rejected';
    if v_reversed < v_credit.amount then
      insert into public.order_review_flags (order_id, user_id, reason, wallet_amount, referral_discount, details)
      values (v_order.id, v_credit.user_id, 'referral_credit_unrecovered', 0, 0,
              jsonb_build_object(
                'credit_ledger_id', v_credit.id,
                'credit_amount', v_credit.amount,
                'reversed', v_reversed,
                'unrecovered', v_credit.amount - v_reversed,
                'razorpay_payment_id', p_razorpay_payment_id,
                'recommended_action',
                  'The friend''s payment was reversed but the referrer had already spent part of the credit. '
                  || 'Only what was still in their wallet was taken back; decide whether to recover the rest.'))
      on conflict (order_id, reason) where order_id is not null do nothing;
    end if;
    v_status := jsonb_build_object('status', 'credit_reversed', 'ledger_id', v_credit.id,
                                   'amount', v_credit.amount, 'reversed', v_reversed);
  end if;

  return v_status || jsonb_build_object('wallet_restored', v_restored, 'purchases_revoked', v_revoked);
end;
$function$

CREATE OR REPLACE FUNCTION public.reverse_play_payment(p_purchase_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid;
  v_order public.orders%rowtype;
  v_credit public.wallet_ledger%rowtype;
  v_restored numeric(10, 2) := 0;
  v_revoked integer := 0;
  v_avail numeric(10, 2);
  v_reversed numeric(10, 2);
  v_status jsonb;
begin
  -- Same lock order as settle_play_purchase (wallet lock, THEN the order row)
  -- so a refund cannot deadlock with a replayed capture event.
  select user_id into v_uid from public.orders where purchase_token = p_purchase_token and provider = 'play';
  if v_uid is not null then
    perform pg_advisory_xact_lock(hashtextextended('wallet:' || v_uid::text, 0));
  end if;

  select * into v_order from public.orders where purchase_token = p_purchase_token and provider = 'play' for update;
  if not found then return jsonb_build_object('status', 'unknown_payment'); end if;

  -- ---- Take the access back ----------------------------------------------
  update public.orders set status = 'refunded', updated_at = now()
   where id = v_order.id and status = 'paid';

  update public.purchases set status = 'refunded'
   where order_id = v_order.id and status not in ('refunded', 'chargeback');
  get diagnostics v_revoked = row_count;

  -- ---- The referrer's credit for this friend's purchase --------------------
  -- Looked up by the ledger row's own order_id, NOT through referrals: the
  -- referrals row is deleted when the friend deletes their account.
  select * into v_credit from public.wallet_ledger
   where order_id = v_order.id and entry_type = 'credit' and source = 'referral_reward'
   for update;

  if not found then
    v_status := jsonb_build_object('status', 'no_referral_credit');

  elsif v_credit.status = 'cancelled' then
    v_status := jsonb_build_object('status', 'already_cancelled');

  elsif v_credit.status = 'pending' then
    -- Still held (even if the hold has technically run out but the release job
    -- has not run yet): cancel it.
    perform set_config('app.trusted_order_write', 'true', true);
    update public.wallet_ledger set status = 'cancelled' where id = v_credit.id;
    perform set_config('app.trusted_order_write', 'false', true);
    update public.referrals
       set status = 'rejected', reject_reason = 'friend_payment_reversed'
     where id = v_credit.referral_id and status <> 'rejected';
    v_status := jsonb_build_object('status', 'credit_cancelled', 'amount', v_credit.amount);

  elsif exists (select 1 from public.wallet_ledger
                 where entry_type = 'reversal' and reverses_id = v_credit.id) then
    v_status := jsonb_build_object('status', 'already_reversed', 'ledger_id', v_credit.id);

  elsif v_credit.user_id is null then
    v_status := jsonb_build_object('status', 'referrer_gone', 'ledger_id', v_credit.id);

  elsif v_credit.expires_at is not null and v_credit.expires_at <= now() then
    v_status := jsonb_build_object('status', 'credit_expired', 'ledger_id', v_credit.id);

  else
    -- Released ('available'): reverse it with a ledger row, but never by more
    -- than the referrer still has (the ledger refuses to overdraw). What cannot
    -- be recovered is flagged for a manual decision.
    perform pg_advisory_xact_lock(hashtextextended('wallet:' || v_credit.user_id::text, 0));
    select available into v_avail from public.wallet_balance_of(v_credit.user_id);
    v_reversed := least(v_credit.amount, coalesce(v_avail, 0));
    if v_reversed > 0 then
      perform set_config('app.trusted_order_write', 'true', true);
      insert into public.wallet_ledger (user_id, entry_type, status, amount, source, reverses_id, referral_id, order_id, note)
      values (v_credit.user_id, 'reversal', 'available', v_reversed, 'order_refund', v_credit.id, v_credit.referral_id, v_order.id,
              'Friend''s payment was reversed')
      on conflict (reverses_id) where entry_type = 'reversal' do nothing;
      perform set_config('app.trusted_order_write', 'false', true);
    end if;
    update public.referrals
       set status = 'rejected', reject_reason = 'friend_payment_reversed'
     where id = v_credit.referral_id and status <> 'rejected';
    if v_reversed < v_credit.amount then
      insert into public.order_review_flags (order_id, user_id, reason, wallet_amount, referral_discount, details)
      values (v_order.id, v_credit.user_id, 'referral_credit_unrecovered', 0, 0,
              jsonb_build_object(
                'credit_ledger_id', v_credit.id,
                'credit_amount', v_credit.amount,
                'reversed', v_reversed,
                'unrecovered', v_credit.amount - v_reversed,
                'order_id', v_order.id,
                'recommended_action',
                  'The friend''s payment was reversed but the referrer had already spent part of the credit. '
                  || 'Only what was still in their wallet was taken back; decide whether to recover the rest.'))
      on conflict (order_id, reason) where order_id is not null do nothing;
    end if;
    v_status := jsonb_build_object('status', 'credit_reversed', 'ledger_id', v_credit.id,
                                   'amount', v_credit.amount, 'reversed', v_reversed);
  end if;

  return v_status || jsonb_build_object('wallet_restored', v_restored, 'purchases_revoked', v_revoked);
end;
$function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.rotate_play_price_sku(p_price numeric, p_lease uuid, p_reason text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_new text;
begin
  v_new := 'notes_' || replace(p_price::numeric(10,2)::text, '.', '_') || '_v_' || replace(gen_random_uuid()::text, '-', '');
  update public.play_price_sync set candidate_sku=v_new, updated_at=now()
    where price_inr=p_price and lease_id=p_lease and status='running' and lease_until>now();
  if not found then raise exception 'Play sync lease lost'; end if;
  update public.play_price_tiers set active=false where price_inr=p_price and active;
  insert into public.play_price_sync_logs(price_inr,play_sku,event,detail)
    values(p_price,v_new,'rotated',left(p_reason,200));
  return v_new;
end; $function$

CREATE OR REPLACE FUNCTION public.save_note_with_upload(p_request_id uuid, p_note_id text, p_title text, p_description text, p_chapter_id text, p_order integer, p_active boolean, p_is_free_preview boolean)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_upload public.note_upload_requests%rowtype;
  v_payload jsonb;
  v_note_id text;
begin
  if not public.am_i_admin() then
    raise exception 'Admin access required' using errcode = '42501';
  end if;
  if p_request_id is null or p_title is null or length(btrim(p_title)) not between 1 and 200
     or p_description is null or length(p_description) > 2000
     or p_chapter_id is null or p_order is null or p_order < 1
     or p_active is null or p_is_free_preview is null then
    raise exception 'Invalid note data' using errcode = '22023';
  end if;
  v_payload := jsonb_build_object('note_id',p_note_id,'title',btrim(p_title),
    'description',p_description,'chapter_id',p_chapter_id,'order',p_order,
    'active',p_active,'is_free_preview',p_is_free_preview);
  select * into v_upload from public.note_upload_requests
    where request_id = p_request_id for update;
  if not found or v_upload.admin_user_id <> auth.uid() then
    raise exception 'Upload request unavailable' using errcode = '42501';
  end if;
  if v_upload.status = 'attached' then
    if v_upload.save_payload is distinct from v_payload then
      raise exception 'Upload request already used for another note change' using errcode = '23505';
    end if;
    if v_upload.note_id is null or not exists (
      select 1 from public.notes where id = v_upload.note_id
    ) then
      raise exception 'Previously saved note was deleted; start a new upload request' using errcode = '22023';
    end if;
    return v_upload.note_id;
  end if;
  if v_upload.status <> 'uploaded' then
    raise exception 'PDF upload is incomplete' using errcode = '22023';
  end if;
  if p_note_id is null then
    insert into public.notes(title,description,pdf_url,chapter_id,"order",active,is_free_preview)
    values(btrim(p_title),p_description,v_upload.pdf_url,p_chapter_id,p_order,p_active,p_is_free_preview)
    returning id into v_note_id;
  else
    update public.notes set title=btrim(p_title),description=p_description,
      pdf_url=v_upload.pdf_url,chapter_id=p_chapter_id,"order"=p_order,
      active=p_active,is_free_preview=p_is_free_preview
    where id=p_note_id returning id into v_note_id;
    if v_note_id is null then
      raise exception 'Note unavailable' using errcode = '22023';
    end if;
  end if;
  update public.note_upload_requests set status='attached',note_id=v_note_id,
    save_payload=v_payload,updated_at=now() where request_id=p_request_id;
  return v_note_id;
end $function$

CREATE OR REPLACE FUNCTION public.set_admin_mfa_required(p_required boolean)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare missing text;
begin
  if p_required then
    select string_agg(a.email, ', ') into missing
      from public.admins a
     where not exists (select 1 from auth.mfa_factors f
                        where f.user_id = a.id and f.status = 'verified');
    if missing is not null then
      raise exception 'Refusing to require MFA: these admins have no verified factor yet: %', missing;
    end if;
  end if;
  update public.admin_settings set require_mfa = p_required, updated_at = now() where id;
  return case when p_required then 'admin MFA is now REQUIRED' else 'admin MFA requirement is OFF' end;
end $function$

CREATE OR REPLACE FUNCTION public.set_my_course_year(p_course_id text, p_year_id text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_course_active boolean;
  v_year_course_id text;
  v_updated bigint;
begin
  if v_uid is null then
    raise exception 'Not authenticated';
  end if;

  select active into v_course_active from public.courses where id = p_course_id;
  if v_course_active is null then
    raise exception 'Unknown course: %', p_course_id;
  end if;
  if not v_course_active then
    raise exception 'Course % is not active', p_course_id;
  end if;

  if p_year_id is not null then
    select course_id into v_year_course_id from public.years where id = p_year_id and active = true;
    if v_year_course_id is null then
      raise exception 'Unknown or inactive year: %', p_year_id;
    end if;
    if v_year_course_id is distinct from p_course_id then
      raise exception 'Year % does not belong to course %', p_year_id, p_course_id;
    end if;
  end if;

  -- Only auth.uid() is eligible for repair; names/email/phone come from the
  -- same auth.users source as signup. Existing profile values are preserved.
  perform public.backfill_auth_user_profile(v_uid);
  perform set_config('app.allow_profile_admin_fields', 'true', true);
  update public.profiles
     set course_id = p_course_id, year_id = p_year_id, updated_at = now()
   where id = v_uid;
  get diagnostics v_updated = row_count;
  perform set_config('app.allow_profile_admin_fields', 'false', true);

  if v_updated <> 1 then
    raise exception 'Could not save your course and year. Please try again.';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.settle_play_purchase(p_user_id uuid, p_order_id text, p_product_id text, p_play_sku text, p_purchase_token text, p_paid_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_order public.orders%rowtype; v_product public.products%rowtype;
  v_other_order text; v_owned_purchase text;
  v_ref public.referrals%rowtype; v_set public.referral_settings%rowtype;
begin
  if p_purchase_token is null or length(p_purchase_token)<10 or length(p_purchase_token)>4096
     or p_paid_at is null then raise exception 'Invalid Play settlement inputs'; end if;
  perform pg_advisory_xact_lock(hashtextextended('wallet:' || p_user_id::text,0));
  select * into v_order from public.orders where id=p_order_id for update;
  if not found or v_order.user_id is distinct from p_user_id or v_order.product_id is distinct from p_product_id
     or v_order.provider<>'play' or v_order.play_sku is distinct from p_play_sku
     or v_order.external_transaction_token is not null or v_order.external_choice_bound_order_id is not null then
    raise exception 'Play order ownership or product mismatch';
  end if;
  if v_order.status='paid' then
    if v_order.purchase_token=p_purchase_token then
      return jsonb_build_object('ok',true,'already_settled',true,'amount',v_order.amount,
        'duplicate',exists(select 1 from public.purchases
          where order_id=v_order.id and status='duplicate'));
    end if;
    raise exception 'Play order already paid with different token';
  end if;
  -- A pending Play purchase can complete after the local checkout timer; once
  -- Google binds its token to this order, charging the user must still unlock it.
  if v_order.status not in ('created','cancelled') then
    raise exception 'Play order unavailable';
  end if;
  select order_id into v_other_order from public.payments where purchase_token=p_purchase_token;
  if found and v_other_order<>p_order_id then raise exception 'Play token already used for another order'; end if;
  select * into v_product from public.products where id=v_order.product_id;
  if not found then raise exception 'Play product unavailable'; end if;
  if not exists(select 1 from public.play_price_tiers where play_sku=v_order.play_sku and price_inr=v_order.amount)
     or v_order.list_price is distinct from v_order.amount or v_order.wallet_amount<>0
     or v_order.referral_discount<>0 then raise exception 'Play order price mismatch'; end if;

  insert into public.payments(order_id,user_id,product_id,amount,provider,purchase_token,play_sku,status,verified_at)
  values(v_order.id,v_order.user_id,v_order.product_id,v_order.amount,'play',p_purchase_token,v_order.play_sku,'success',now());
  select id into v_owned_purchase from public.purchases
   where user_id=v_order.user_id and product_id=v_product.id and status='success' and order_id is distinct from v_order.id limit 1;
  insert into public.purchases(user_id,order_id,product_id,product_title,scope,chapter_id,subject_id,year_id,
    year_ids,course_id,amount,status)
  values(v_order.user_id,v_order.id,v_product.id,coalesce(v_product.title,'Your content'),v_product.scope,
    v_product.chapter_id,v_product.subject_id,v_product.year_id,v_product.year_ids,v_product.course_id,
    v_order.amount,case when v_owned_purchase is null then 'success' else 'duplicate' end);
  update public.orders set status='paid',purchase_token=p_purchase_token,play_consumption_status='pending',
    payment_completed_at=p_paid_at,updated_at=now() where id=v_order.id;
  if v_owned_purchase is null then perform public.record_purchase_identity(v_order.user_id); end if;

  -- Mirror the referral section of settle_razorpay_payment exactly: a duplicate
  -- paid product is not a first purchase and never earns another credit.
  select * into v_ref from public.referrals where referred_id=v_order.user_id for update;
  if found and v_ref.first_order_id is null and v_ref.status in ('pending','qualified')
     and v_owned_purchase is null
     and not exists(select 1 from public.purchases where user_id=v_order.user_id
                    and order_id<>v_order.id and status='success') then
    select * into v_set from public.referral_settings where id=true;
    if v_set.require_verified_phone
       and not (coalesce((select mobile_verified from public.profiles where id=v_order.user_id),false)
            and coalesce((select mobile_verified from public.profiles where id=v_ref.referrer_id),false)) then
      update public.referrals set first_order_id=v_order.id,status='rejected',
        reject_reason='phone_not_verified_at_purchase' where id=v_ref.id;
      v_ref.status:='rejected';
    elsif public.has_prior_purchase_identity(v_order.user_id) then
      update public.referrals set first_order_id=v_order.id,status='rejected',
        reject_reason='returning_customer' where id=v_ref.id;
      v_ref.status:='rejected';
    else
      update public.referrals set first_order_id=v_order.id,status='qualified',
        qualified_at=coalesce(qualified_at,now()) where id=v_ref.id;
    end if;
    if v_ref.status<>'rejected' and v_set.enabled and v_set.referrer_credit_amount>0
       and exists(select 1 from public.profiles where id=v_ref.referrer_id and not blocked) then
      insert into public.wallet_ledger(user_id,entry_type,status,amount,source,referral_id,order_id,
        available_at,expires_at,note)
      values(v_ref.referrer_id,'credit','pending',v_set.referrer_credit_amount::numeric(10,2),
        'referral_reward',v_ref.id,v_order.id,
        now()+make_interval(days=>v_set.credit_hold_days),
        case when v_set.credit_expiry_days is null then null
          else now()+make_interval(days=>v_set.credit_hold_days+v_set.credit_expiry_days) end,
        'Friend''s first purchase')
      on conflict (referral_id) where entry_type='credit' and source='referral_reward' do nothing;
    end if;
  end if;
  return jsonb_build_object('ok',true,'already_settled',false,'amount',v_order.amount,
    'duplicate',v_owned_purchase is not null);
end; $function$

CREATE OR REPLACE FUNCTION public.settle_razorpay_payment(p_event_id text, p_razorpay_order_id text, p_razorpay_payment_id text, p_amount_paise bigint, p_paid_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_order public.orders%rowtype; v_capture public.payment_captures%rowtype;
  v_reason text; v_reversal boolean; v_error text; v_uid uuid;
begin
  -- Match creation, refund and legacy settlement lock order: user, then order.
  select user_id into v_uid from public.orders where razorpay_order_id=p_razorpay_order_id;
  if v_uid is not null then
    perform pg_advisory_xact_lock(hashtextextended('wallet:' || v_uid::text,0));
  end if;
  select * into v_order from public.orders where razorpay_order_id=p_razorpay_order_id for update;
  if not found then raise exception 'Razorpay order is not linked'; end if;
  if round(v_order.amount*100)::bigint<>p_amount_paise then raise exception 'capture amount mismatch'; end if;
  perform public.record_payment_capture(p_razorpay_payment_id,p_razorpay_order_id,p_amount_paise,null);
  select * into v_capture from public.payment_captures where payment_id=p_razorpay_payment_id for update;
  if v_capture.status in ('compensation_pending','compensated') then
    update public.provider_events set status='applied'
      where event_id=p_event_id and event_type='payment.captured';
    return;
  end if;
  if v_order.razorpay_payment_id is not null and v_order.razorpay_payment_id<>p_razorpay_payment_id then
    insert into public.payment_compensations(payment_id,order_id,amount_paise,reason,refund_request_id)
      values(p_razorpay_payment_id,v_order.id,p_amount_paise,'additional_capture',
        'medveda_comp_' || md5(p_razorpay_payment_id)) on conflict(payment_id) do nothing;
    update public.payment_captures set status='compensation_pending',failure_reason='additional_capture'
      where payment_id=p_razorpay_payment_id;
    update public.provider_events set status='applied' where event_id=p_event_id and event_type='payment.captured';
    return;
  end if;
  -- Link the verified capture so an earlier reversal inbox can be reconciled
  -- even while entitlement is held. This does not mark the order paid.
  update public.orders set razorpay_payment_id=p_razorpay_payment_id
    where id=v_order.id and razorpay_payment_id is null;
  -- A successful capture replay must not become stale merely because time passed.
  -- Reversals still take precedence and never restore access.
  if v_capture.status='granted' and v_order.status='paid' then
    update public.provider_events set status='applied'
      where event_id=p_event_id and event_type='payment.captured';
    return;
  end if;
  -- Unknown reversal facts and open disputes HOLD settlement. A later won
  -- dispute clears the hold; an authenticated full refund/lost dispute reverses.
  -- Never infer a full refund from a refund.processed event alone.
  if v_order.status<>'refunded' and v_capture.status<>'reversed' and exists(
    select 1 from public.provider_events e where e.payment_id=p_razorpay_payment_id
      and e.status in ('pending','applied')
      and e.event_type in ('refund.processed','payment.dispute.created','payment.dispute.under_review',
        'payment.dispute.action_required','payment.dispute.lost')
      and (e.blocks_entitlement is null or (e.blocks_entitlement and
        e.event_type in ('payment.dispute.created','payment.dispute.under_review','payment.dispute.action_required')))) then
    return;
  end if;
  select v_order.status='refunded' or v_capture.status='reversed' or exists(
    select 1 from public.provider_events e where e.payment_id=p_razorpay_payment_id
      and e.blocks_entitlement and e.status in ('pending','applied')
      and e.event_type in ('refund.processed','payment.dispute.lost')) into v_reversal;
  if v_reversal then v_reason:='reversal_received';
  elsif v_order.user_id is null then v_reason:='account_deleted';
  elsif v_order.scope is null or v_order.scope not in ('chapter','subject','year','bundle')
      or (v_order.scope='chapter' and v_order.chapter_id is null)
      or (v_order.scope='subject' and v_order.subject_id is null)
      or (v_order.scope='year' and v_order.year_id is null)
      or (v_order.scope='bundle' and coalesce(array_length(v_order.year_ids,1),0)=0)
      or v_order.course_id is null then v_reason:='missing_entitlement_snapshot';
  elsif v_order.referral_discount>0 and (v_order.status in ('cancelled','failed')
      or (v_order.expires_at is not null and coalesce(p_paid_at,now())>v_order.expires_at)) then
    v_reason:='stale_discount';
  elsif v_order.referral_discount>0 and not exists(select 1 from public.first_discount_reservations
      where order_id=v_order.id and user_id=v_order.user_id) then v_reason:='discount_reused';
  elsif exists(select 1 from public.purchases where user_id=v_order.user_id
      and product_id=v_order.product_id and status='success' and order_id is distinct from v_order.id) then
    v_reason:='already_owned';
  elsif v_order.amount<>v_order.list_price-v_order.referral_discount-v_order.wallet_amount then
    v_reason:='underpriced_order';
  end if;
  if v_reason is null then
    begin
      perform public.settle_razorpay_payment_legacy(p_event_id,p_razorpay_order_id,
        p_razorpay_payment_id,p_amount_paise,p_paid_at);
    exception when others then
      v_error:=sqlerrm;
      if v_error like 'wallet shortfall:%' then v_reason:='wallet_shortfall';
      else raise; end if;
    end;
  end if;
  if v_reason is not null then
    update public.orders set status=case when v_reversal then 'refunded' else 'paid' end,
      razorpay_payment_id=p_razorpay_payment_id, updated_at=now(),
      payment_completed_at=coalesce(payment_completed_at,clock_timestamp())
      where id=v_order.id and status<>'refunded';
    insert into public.payment_compensations(payment_id,order_id,amount_paise,reason,refund_request_id)
      select p_razorpay_payment_id,v_order.id,p_amount_paise,v_reason,
        'medveda_comp_' || md5(p_razorpay_payment_id)
      where not v_reversal on conflict(payment_id) do nothing;
    update public.payment_captures set status=case when v_reversal then 'reversed' else 'compensation_pending' end,
      failure_reason=v_reason where payment_id=p_razorpay_payment_id;
  else
    if not public.razorpay_entitlement_committed(v_order.id,p_razorpay_payment_id) then
      raise exception 'Razorpay entitlement not committed';
    end if;
    update public.payment_captures set status='granted' where payment_id=p_razorpay_payment_id;
  end if;
  update public.orders set payment_provider_time=coalesce(payment_provider_time,v_capture.provider_time),
    payment_received_at=coalesce(payment_received_at,v_capture.received_at),
    payment_completed_at=coalesce(payment_completed_at,clock_timestamp()),
    payment_time_fallback=(v_capture.provider_time is null)
    where id=v_order.id;
  update public.provider_events set status='applied'
    where event_id=p_event_id and event_type='payment.captured';
end $function$

CREATE OR REPLACE FUNCTION public.settle_razorpay_payment_legacy(p_event_id text, p_razorpay_order_id text, p_razorpay_payment_id text, p_amount_paise bigint, p_paid_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid;
  v_order public.orders%rowtype;
  v_product public.products%rowtype;
  v_existing_payment_order_id text;
  v_set public.referral_settings%rowtype;
  v_ref public.referrals%rowtype;
  v_balance numeric(10, 2);
  v_debit numeric(10, 2) := 0;
  v_stale boolean;
  v_first boolean;                 -- first settlement of this order (not a replay)
  v_debited boolean := false;
  v_discount_owner text;
  v_discount_dup boolean := false;
  v_owned_purchase text;           -- an existing successful purchase of the same product
  v_base jsonb;
  v_other_reserved numeric(10,2);
begin
  if p_event_id is null or p_razorpay_order_id is null or p_razorpay_payment_id is null
    or p_amount_paise is null or p_amount_paise <= 0 then
    raise exception 'invalid Razorpay settlement parameters';
  end if;

  select user_id into v_uid from public.orders where razorpay_order_id = p_razorpay_order_id;
  if v_uid is not null then
    perform pg_advisory_xact_lock(hashtextextended('wallet:' || v_uid::text, 0));
  end if;

  -- Row lock serialises a webhook retry with the client verification path.
  select * into v_order
  from public.orders
  where razorpay_order_id = p_razorpay_order_id
  for update;

  if not found then
    raise exception 'Razorpay order % is not linked to an internal order', p_razorpay_order_id;
  end if;
  if round(v_order.amount * 100)::bigint <> p_amount_paise then
    raise exception 'Razorpay amount does not match order amount';
  end if;

  select order_id into v_existing_payment_order_id
  from public.payments
  where razorpay_payment_id = p_razorpay_payment_id;
  if found and v_existing_payment_order_id <> v_order.id then
    raise exception 'Razorpay payment is already linked to another order';
  end if;

  -- Account deleted while the payment was in flight: keep the accounting row,
  -- grant nothing, debit nothing, reward nothing (refund manually).
  if v_order.user_id is null then
    insert into public.payments (
      order_id, user_id, product_id, amount, razorpay_order_id,
      razorpay_payment_id, status, verified_at
    ) values (
      v_order.id, null, v_order.product_id, v_order.amount,
      p_razorpay_order_id, p_razorpay_payment_id, 'success', now()
    ) on conflict (razorpay_payment_id) do nothing;

    update public.orders
    set status = 'paid', razorpay_payment_id = p_razorpay_payment_id, updated_at = now(),
        payment_completed_at = case when external_transaction_token is not null
          then coalesce(payment_completed_at, clock_timestamp()) else payment_completed_at end
    where id = v_order.id and status <> 'refunded';

    insert into public.razorpay_webhook_events(event_id, razorpay_payment_id, event_type)
    values (p_event_id, p_razorpay_payment_id, 'payment.captured')
    on conflict (event_id) do nothing;

    raise warning 'grant_razorpay_payment: payment % for order % arrived after the account was deleted; no access granted - refund manually', p_razorpay_payment_id, v_order.id;
    return;
  end if;

  select * into v_product from public.products where id = v_order.product_id;
  if not found then
    raise exception 'Order % references unknown product %', v_order.id, v_order.product_id;
  end if;

  v_first := v_order.status not in ('paid', 'refunded');

  -- A cancelled/expired checkout may have released its reservation. Never
  -- grant a captured payment unless the whole wallet discount can be debited.
  if v_first and v_order.wallet_amount > 0 then
    perform public.release_due_wallet_credits(v_order.user_id);
    select available into v_balance from public.wallet_balance_of(v_order.user_id);
    select coalesce(sum(r.amount),0) into v_other_reserved
      from public.wallet_order_reservations r join public.orders o on o.id=r.order_id
      where r.user_id=v_order.user_id and r.order_id<>v_order.id
        and o.status='created' and r.expires_at>now();
    if coalesce(v_balance,0)-v_other_reserved < v_order.wallet_amount then
      raise exception 'wallet shortfall: captured payment requires manual refund or compensation';
    end if;
  end if;

  -- ---- Friend discount is usable ONCE per referral -------------------------
  -- The first discounted order to settle claims referrals.discount_order_id; any
  -- other discounted order is a second use of the same discount. Serialised per
  -- user by the wallet advisory lock above; replays of the winner see their own
  -- id and pass. A second use is still granted (the customer paid what checkout
  -- charged) but gets no referrer credit, and is flagged below.
  if v_order.referral_discount > 0 and v_order.referral_id is not null then
    update public.referrals set discount_order_id = v_order.id
     where id = v_order.referral_id and discount_order_id is null;
    select discount_order_id into v_discount_owner from public.referrals where id = v_order.referral_id;
    v_discount_dup := found and v_discount_owner is not null and v_discount_owner <> v_order.id;
  end if;

  insert into public.payments (
    order_id, user_id, product_id, amount, razorpay_order_id,
    razorpay_payment_id, status, verified_at
  ) values (
    v_order.id, v_order.user_id, v_order.product_id, v_order.amount,
    p_razorpay_order_id, p_razorpay_payment_id, 'success', now()
  ) on conflict (razorpay_payment_id) do nothing;

  -- ---- Already owns this product? -----------------------------------------
  select id into v_owned_purchase from public.purchases
   where user_id = v_order.user_id and product_id = v_product.id
     and status = 'success' and order_id is distinct from v_order.id
   limit 1;

  insert into public.purchases (
    user_id, order_id, product_id, product_title, scope, chapter_id,
    subject_id, year_id, year_ids, course_id, amount, status, razorpay_order_id
  ) values (
    v_order.user_id, v_order.id, v_product.id, coalesce(v_product.title, 'Your content'),
    v_order.scope, v_order.chapter_id, v_order.subject_id, v_order.year_id,
    v_order.year_ids, v_order.course_id, v_order.amount,
    case when v_owned_purchase is null then 'success' else 'duplicate' end,
    p_razorpay_order_id
  ) on conflict (order_id) do nothing;

  update public.orders
  set status = 'paid', razorpay_payment_id = p_razorpay_payment_id,
      course_id = v_order.course_id, updated_at = now(),
      payment_completed_at = case when external_transaction_token is not null
        then coalesce(payment_completed_at, clock_timestamp()) else payment_completed_at end
  where id = v_order.id and status <> 'refunded';

  -- Remember who bought (hashed email / phone) so a deleted-and-recreated account is not
  -- treated as a first-time buyer. Never removed on refund or account deletion.
  if v_owned_purchase is null then
    perform public.record_purchase_identity(v_order.user_id);
  end if;

  -- ---- Stale order? -------------------------------------------------------
  -- v_order is the row as it was BEFORE this settlement flipped it to 'paid'.
  -- Replays see 'paid' and rely on the flag written the first time.
  v_stale := exists (select 1 from public.order_review_flags
                      where order_id = v_order.id and reason = 'stale_order_paid')
          or v_order.status in ('cancelled', 'failed')
          or (v_order.status = 'created' and v_order.expires_at is not null
              and coalesce(p_paid_at, now()) > v_order.expires_at);

  -- ---- Wallet debit: ALWAYS, on the first settlement, clamped ---------------
  if v_first and v_order.wallet_amount > 0
     and not exists (select 1 from public.wallet_ledger
                      where order_id = v_order.id and entry_type = 'debit' and source = 'order_payment') then
    perform public.release_due_wallet_credits(v_order.user_id);
    select available into v_balance from public.wallet_balance_of(v_order.user_id);
    v_debit := v_order.wallet_amount;
    if v_debit > 0 then
      insert into public.wallet_ledger (user_id, entry_type, status, amount, source, order_id, note)
      values (v_order.user_id, 'debit', 'available', v_debit, 'order_payment', v_order.id, 'Wallet used at checkout')
      on conflict (order_id) where entry_type = 'debit' and source = 'order_payment' do nothing;
      v_debited := true;
    end if;
  end if;

  -- ---- Review flags (one per order and reason; replays add nothing) ---------
  v_base := jsonb_build_object(
    'product_id', v_product.id,
    'product_title', v_product.title,
    'amount_paid', v_order.amount,
    'list_price', v_order.list_price,
    'razorpay_order_id', p_razorpay_order_id,
    'razorpay_payment_id', p_razorpay_payment_id);

  if v_first and v_order.wallet_amount > 0 and v_debit < v_order.wallet_amount then
    insert into public.order_review_flags (order_id, user_id, reason, wallet_amount, referral_discount, details)
    values (v_order.id, v_order.user_id, 'wallet_shortfall', v_order.wallet_amount, v_order.referral_discount,
            v_base || jsonb_build_object(
              'wallet_amount_applied', v_order.wallet_amount,
              'wallet_debited', v_debit,
              'shortfall', v_order.wallet_amount - v_debit,
              'access_granted', true,
              'recommended_action',
                format('Checkout applied Rs %s of wallet balance but only Rs %s was still available, so Rs %s of the discount was not paid for. Access was granted. Decide whether to accept it or refund payment %s in Razorpay (a full refund revokes the access).',
                       v_order.wallet_amount, v_debit, v_order.wallet_amount - v_debit, p_razorpay_payment_id)))
    on conflict (order_id, reason) where order_id is not null do nothing;
    raise warning 'settle_razorpay_payment: order % wanted % wallet credit but only % was available',
      v_order.id, v_order.wallet_amount, v_debit;
  end if;

  if v_stale and (v_order.wallet_amount > 0 or v_order.referral_discount > 0) then
    insert into public.order_review_flags (order_id, user_id, reason, wallet_amount, referral_discount, details)
    values (v_order.id, v_order.user_id, 'stale_order_paid', v_order.wallet_amount, v_order.referral_discount,
            v_base || jsonb_build_object(
              'order_status', v_order.status, 'expires_at', v_order.expires_at, 'paid_at', p_paid_at,
              'wallet_debited', (select coalesce(sum(amount), 0) from public.wallet_ledger
                                  where order_id = v_order.id and entry_type = 'debit' and source = 'order_payment'),
              'access_granted', true,
              'recommended_action',
                'This payment arrived for a checkout that was already cancelled or had expired. Access was granted and the wallet amount was debited as normal. No action needed unless the amount looks wrong.'))
    on conflict (order_id, reason) where order_id is not null do nothing;
    raise warning 'settle_razorpay_payment: order % was % / expired when payment % arrived; flagged for review',
      v_order.id, v_order.status, p_razorpay_payment_id;
  end if;

  if v_discount_dup then
    insert into public.order_review_flags (order_id, user_id, reason, wallet_amount, referral_discount, details)
    values (v_order.id, v_order.user_id, 'discount_reused', v_order.wallet_amount, v_order.referral_discount,
            v_base || jsonb_build_object(
              'discount_first_order_id', v_discount_owner,
              'discount_not_owed', v_order.referral_discount,
              'order_status', v_order.status,
              'access_granted', true,
              'referrer_credited', false,
              'recommended_action',
                format('Access was granted. This student already used their one friend discount on order %s, so this order was under-charged by Rs %s (paid Rs %s instead of Rs %s). To reverse it, issue a FULL refund of payment %s in the Razorpay dashboard: the refund webhook then revokes the access and gives back any wallet amount used, and the student can buy again at full price. Do nothing to keep the sale as it is.',
                       v_discount_owner, v_order.referral_discount, v_order.amount,
                       v_order.amount + v_order.referral_discount, p_razorpay_payment_id)))
    on conflict (order_id, reason) where order_id is not null do nothing;
    raise warning 'settle_razorpay_payment: order % reuses the friend discount already used by order %; access granted, no referrer credit, flagged for review',
      v_order.id, v_discount_owner;
  end if;

  if v_owned_purchase is not null then
    insert into public.order_review_flags (order_id, user_id, reason, wallet_amount, referral_discount, details)
    values (v_order.id, v_order.user_id, 'duplicate_purchase', v_order.wallet_amount, v_order.referral_discount,
            v_base || jsonb_build_object(
              'existing_purchase_id', v_owned_purchase,
              'access_granted', false,
              'recommended_action',
                format('The student already owned "%s" and paid for it again (Rs %s). The new purchase is stored as ''duplicate'' and adds no access. Refund payment %s in the Razorpay dashboard.',
                       v_product.title, v_order.amount, p_razorpay_payment_id)))
    on conflict (order_id, reason) where order_id is not null do nothing;
    raise warning 'settle_razorpay_payment: order % is a duplicate purchase of product %; flagged for refund', v_order.id, v_product.id;
  end if;

  -- ---- Referrer credit ----------------------------------------------------
  -- Only the friend's FIRST successful purchase counts, and only once.
  select * into v_ref from public.referrals where referred_id = v_order.user_id for update;
  if found and not v_discount_dup and v_ref.first_order_id is null and v_ref.status in ('pending', 'qualified')
     and v_owned_purchase is null
     and not exists (select 1 from public.purchases
                      where user_id = v_order.user_id and order_id <> v_order.id and status = 'success') then
    select * into v_set from public.referral_settings where id = true;

    -- Batch 3 / F5: no credit unless BOTH sides have a verified mobile number at the
    -- moment of the purchase (a number changed after applying the code loses its
    -- verification). The referral is consumed: this was the friend's first purchase.
    if v_set.require_verified_phone
       and not (coalesce((select mobile_verified from public.profiles where id = v_order.user_id), false)
            and coalesce((select mobile_verified from public.profiles where id = v_ref.referrer_id), false)) then
      update public.referrals
         set first_order_id = v_order.id, status = 'rejected', reject_reason = 'phone_not_verified_at_purchase'
       where id = v_ref.id;
      raise warning 'settle_razorpay_payment: no referrer credit for order %: a mobile number was not verified', v_order.id;
      v_ref.status := 'rejected';
    elsif public.has_prior_purchase_identity(v_order.user_id) then
      -- Same email / phone already bought under another (maybe deleted) account.
      update public.referrals
         set first_order_id = v_order.id, status = 'rejected', reject_reason = 'returning_customer'
       where id = v_ref.id;
      raise warning 'settle_razorpay_payment: no referrer credit for order %: the buyer is a returning customer', v_order.id;
      v_ref.status := 'rejected';
    else
      update public.referrals
         set first_order_id = v_order.id, status = 'qualified', qualified_at = coalesce(qualified_at, now())
       where id = v_ref.id;
    end if;

    if v_ref.status <> 'rejected' and v_set.enabled and v_set.referrer_credit_amount > 0
       and exists (select 1 from public.profiles where id = v_ref.referrer_id and not blocked) then
      insert into public.wallet_ledger (
        user_id, entry_type, status, amount, source, referral_id, order_id,
        available_at, expires_at, note
      ) values (
        v_ref.referrer_id, 'credit', 'pending', v_set.referrer_credit_amount::numeric(10, 2),
        'referral_reward', v_ref.id, v_order.id,
        now() + make_interval(days => v_set.credit_hold_days),
        case when v_set.credit_expiry_days is null then null
             else now() + make_interval(days => v_set.credit_hold_days + v_set.credit_expiry_days) end,
        'Friend''s first purchase'
      ) on conflict (referral_id) where entry_type = 'credit' and source = 'referral_reward' do nothing;
    end if;
  end if;

  insert into public.razorpay_webhook_events(event_id, razorpay_payment_id, event_type)
  values (p_event_id, p_razorpay_payment_id, 'payment.captured')
  on conflict (event_id) do nothing;
end;
$function$

CREATE OR REPLACE FUNCTION public.subjects_derive_course()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_course_id text;
begin
  select course_id into v_course_id from public.years where id = new.year_id;
  if v_course_id is null then
    raise exception 'Unknown year_id % on subjects', new.year_id;
  end if;
  if new.course_id is null then
    new.course_id := v_course_id;
  elsif new.course_id is distinct from v_course_id then
    raise exception 'subjects.course_id (%) does not match its year''s course (%)', new.course_id, v_course_id;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.subjects_propagate_course_move()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.year_id is distinct from old.year_id or new.course_id is distinct from old.course_id then
    update public.chapters set year_id = new.year_id, course_id = new.course_id
      where subject_id = new.id and (year_id is distinct from new.year_id or course_id is distinct from new.course_id);
    update public.videos set year_id = new.year_id, course_id = new.course_id
      where subject_id = new.id and (year_id is distinct from new.year_id or course_id is distinct from new.course_id);
    update public.quiz_tests set year_id = new.year_id, course_id = new.course_id
      where subject_id = new.id and (year_id is distinct from new.year_id or course_id is distinct from new.course_id);
    update public.products set course_id = new.course_id
      where scope = 'subject' and subject_id = new.id and course_id is distinct from new.course_id;
    -- notes hang off chapters, not subjects; the chapters cascade below reaches them.
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_quiz_attempt(p_attempt_id text, p_test_id text, p_question_revision bigint, p_answers jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_user uuid := auth.uid();
  v_test public.quiz_tests%rowtype;
  v_existing public.verified_quiz_attempts%rowtype;
  v_question jsonb;
  v_selected jsonb;
  v_option_index integer;
  v_total integer;
  v_score integer := 0;
  v_i integer;
begin
  if v_user is null then
    raise exception 'Sign in required' using errcode = '42501';
  end if;
  if not exists (select 1 from public.profiles where id = v_user and not coalesce(blocked, false)) then
    raise exception 'Account unavailable' using errcode = '42501';
  end if;
  if p_attempt_id is null or length(p_attempt_id) not between 8 and 160
     or p_test_id is null or p_question_revision is null
     or p_answers is null or jsonb_typeof(p_answers) <> 'array' then
    raise exception 'Invalid attempt' using errcode = '22023';
  end if;

  -- A dropped response can be retried even after the test has since changed.
  select * into v_existing from public.verified_quiz_attempts where id = p_attempt_id;
  if found then
    if v_existing.user_id <> v_user or v_existing.test_id is distinct from p_test_id
       or v_existing.question_revision <> p_question_revision or v_existing.answers <> p_answers then
      raise exception 'Attempt id belongs to another submission' using errcode = '23505';
    end if;
    return jsonb_build_object('status','verified','score',v_existing.score,
      'total',v_existing.total,'percentage',v_existing.percentage);
  end if;

  if not public.rate_limit_hit('verified-quiz:' || v_user::text, 120, 3600) then
    return jsonb_build_object('status','rate_limited');
  end if;

  select * into v_test from public.quiz_tests where id = p_test_id and active;
  if not found
     or not public.content_is_published(v_test.course_id, v_test.year_id, v_test.subject_id)
     or not public.has_content_access(v_test.course_id, v_test.year_id) or not exists (
    select 1 from public.subjects s where s.id = v_test.subject_id
      and s.year_id = v_test.year_id and s.course_id = v_test.course_id
  ) then
    raise exception 'Test unavailable' using errcode = '22023';
  end if;
  if v_test.question_revision <> p_question_revision then
    return jsonb_build_object('status','stale');
  end if;
  if jsonb_typeof(v_test.questions) <> 'array' then
    raise exception 'Test questions invalid' using errcode = '22023';
  end if;
  v_total := jsonb_array_length(v_test.questions);
  if v_total < 1 or v_total > 100 or jsonb_array_length(p_answers) <> v_total then
    raise exception 'Answer count mismatch' using errcode = '22023';
  end if;

  for v_i in 0..v_total-1 loop
    v_question := v_test.questions -> v_i;
    v_selected := p_answers -> v_i;
    if jsonb_typeof(v_question) <> 'object'
       or jsonb_typeof(v_question->'options') <> 'array'
       or jsonb_typeof(v_question->'answer') <> 'string'
       or jsonb_array_length(v_question->'options') < 2 then
      raise exception 'Test question invalid' using errcode = '22023';
    end if;
    if v_selected = 'null'::jsonb then continue; end if;
    if jsonb_typeof(v_selected) <> 'number' or (v_selected #>> '{}') !~ '^[0-9]+$' then
      raise exception 'Answer index invalid' using errcode = '22023';
    end if;
    v_option_index := (v_selected #>> '{}')::integer;
    if v_option_index >= jsonb_array_length(v_question->'options') then
      raise exception 'Answer index out of range' using errcode = '22023';
    end if;
    if v_question->'options'->>v_option_index = v_question->>'answer' then
      v_score := v_score + 1;
    end if;
  end loop;

  insert into public.verified_quiz_attempts
    (id,user_id,test_id,test_title,subject_id,question_revision,answers,score,total,percentage)
  values (p_attempt_id,v_user,p_test_id,v_test.title,v_test.subject_id,p_question_revision,
    p_answers,v_score,v_total,round(v_score * 100.0 / v_total)::integer)
  on conflict (id) do nothing;

  select * into v_existing from public.verified_quiz_attempts where id = p_attempt_id;
  if v_existing.user_id <> v_user or v_existing.test_id is distinct from p_test_id
     or v_existing.question_revision <> p_question_revision or v_existing.answers <> p_answers then
    raise exception 'Attempt id belongs to another submission' using errcode = '23505';
  end if;
  return jsonb_build_object('status','verified','score',v_existing.score,
    'total',v_existing.total,'percentage',v_existing.percentage);
end $function$

CREATE OR REPLACE FUNCTION public.sync_profile_email()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.email is not null and new.email is distinct from old.email then
    perform set_config('app.allow_profile_admin_fields', 'true', true);
    update public.profiles set email = new.email, updated_at = now() where id = new.id;
    perform set_config('app.allow_profile_admin_fields', 'false', true);
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_profile_mobile_verified()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_norm text;
begin
  if new.phone_confirmed_at is null or coalesce(new.phone, '') = '' then return new; end if;
  if tg_op = 'UPDATE' and old.phone_confirmed_at is not distinct from new.phone_confirmed_at
     and old.phone is not distinct from new.phone then
    return new;
  end if;
  v_norm := public.normalize_phone('+' || ltrim(new.phone, '+'));
  if v_norm is null then return new; end if;
  perform set_config('app.allow_profile_admin_fields', 'true', true);
  begin
    update public.profiles set phone = v_norm, mobile_verified = true, updated_at = now() where id = new.id;
  exception when unique_violation then
    null;   -- that number already belongs to another profile: leave this one unverified
  end;
  perform set_config('app.allow_profile_admin_fields', 'false', true);
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.sync_profile_phone_normalized()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.phone_normalized := public.normalize_phone(new.phone);
  if (tg_op = 'INSERT' or new.phone is distinct from old.phone)
    and new.phone is not null
    and btrim(new.phone) <> ''
    and new.phone_normalized is null then
    raise exception 'phone must be a valid E.164 number';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.touch_profile_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.updated_at := now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.videos_derive_course()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_course_id text;
  v_year_id text;
begin
  select course_id, year_id into v_course_id, v_year_id from public.subjects where id = new.subject_id;
  if v_course_id is null then
    raise exception 'Unknown subject_id % on videos', new.subject_id;
  end if;
  if new.course_id is null then
    new.course_id := v_course_id;
  elsif new.course_id is distinct from v_course_id then
    raise exception 'videos.course_id (%) does not match its subject''s course (%)', new.course_id, v_course_id;
  end if;
  if new.year_id is null then
    new.year_id := v_year_id;
  elsif new.year_id is distinct from v_year_id then
    raise exception 'videos.year_id (%) does not match its subject''s year (%)', new.year_id, v_year_id;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.wallet_ledger_append_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if tg_op = 'DELETE' then
    raise exception 'wallet_ledger is append-only' using errcode = '42501';
  end if;

  if new.id            is distinct from old.id
  or new.entry_type    is distinct from old.entry_type
  or new.amount        is distinct from old.amount
  or new.source        is distinct from old.source
  or new.reverses_id   is distinct from old.reverses_id and new.reverses_id is not null
  or new.available_at  is distinct from old.available_at
  or new.expires_at    is distinct from old.expires_at
  or new.note          is distinct from old.note
  or new.created_at    is distinct from old.created_at
  or (new.user_id      is distinct from old.user_id     and new.user_id     is not null)
  or (new.referral_id  is distinct from old.referral_id and new.referral_id is not null)
  or (new.order_id     is distinct from old.order_id    and new.order_id    is not null) then
    raise exception 'wallet_ledger rows are immutable except status' using errcode = '42501';
  end if;

  if new.status is distinct from old.status then
    if not (old.status = 'pending' and new.status in ('available', 'cancelled')) then
      raise exception 'wallet_ledger: illegal status change % -> %', old.status, new.status
        using errcode = '42501';
    end if;
    new.status_changed_at := now();
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.wallet_ledger_no_overdraw()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_bal numeric;
begin
  if new.user_id is null or new.entry_type not in ('debit', 'reversal') or new.status <> 'available' then
    return new;
  end if;
  -- same lock key as create_priced_order / settle_razorpay_payment
  perform pg_advisory_xact_lock(hashtextextended('wallet:' || new.user_id::text, 0));
  select coalesce(sum(amount) filter (where entry_type = 'credit' and status = 'available'
                                        and (expires_at is null or expires_at > now())), 0)
       - coalesce(sum(amount) filter (where entry_type in ('debit', 'reversal') and status = 'available'), 0)
    into v_bal
    from public.wallet_ledger where user_id = new.user_id;
  if v_bal < new.amount then
    raise exception 'wallet_ledger: a % of % would overdraw the wallet (available %)', new.entry_type, new.amount, v_bal
      using errcode = '23514';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.years_before_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'UPDATE' and new.course_id is distinct from old.course_id then
    if exists (select 1 from public.products p where p.scope = 'bundle' and old.id = any(p.year_ids)) then
      raise exception 'Cannot move year % to another course while a bundle product references it; update or remove the bundle first', old.id;
    end if;
  end if;
  return new;
end;
$function$
